function formatMoney(amount) {
  return `$${amount.toFixed(2)}`;
}

function buildHeader(data) {
  return `<h1>Invoice #${data.number}</h1><h2>Billed to: ${data.customer}</h2>`;
}

function buildRow(item) {
  const description = `<td class="desc">${item.description}</td>`;
  const quantity = `<td class="qty">${item.quantity}</td>`;
  const unitPrice = `<td class="price">${formatMoney(item.price)}</td>`;
  const subtotal = `<td class="subtotal">${formatMoney(item.quantity * item.price)}</td>`;
  return `<tr>${description + quantity + unitPrice + subtotal}</tr>`;
}

function validate(data) {
  if (!data || typeof data.number === 'undefined') {
    throw new Error('invoice data must include a number');
  }
  if (!Array.isArray(data.items) || data.items.length === 0) {
    throw new Error(`invoice ${data.number} has no items to bill`);
  }
  data.items.forEach((item, index) => {
    if (!(item.quantity > 0) || !(item.price >= 0)) {
      throw new Error(`item ${index + 1} of invoice ${data.number} has an invalid quantity or price`);
    }
  });
}

function invoice(data) {
  validate(data);
  const tag = 'table';
  const parts = [];
  parts.push(buildHeader(data));
  parts.push(`<${tag} class="invoice">`);
  parts.push('<tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Subtotal</th></tr>');
  let total = 0;
  for (const item of data.items) {
    total += item.quantity * item.price;
    parts.push(buildRow(item));
  }
  parts.push(`<tr class="total"><td colspan="3">Grand total</td><td>${formatMoney(total)}</td></tr>`);
  parts.push(`</${tag}>`);
  parts.push(`<p class="footer">Thank you for your business, ${data.customer}!</p>`);
  return parts;
}

function renderDocument(data) {
  const body = invoice(data).join('\n');
  const title = `Invoice ${data.number} for ${data.customer}`;
  return `<!DOCTYPE html>\n<html>\n<head><title>${title}</title></head>\n<body>\n${body}\n</body>\n</html>`;
}

const sample = {
  number: 'INV-2048',
  customer: 'Ada Lovelace',
  items: [
    { description: 'Analytical engine consulting', quantity: 12, price: 145.5 },
    { description: 'Punch card set', quantity: 250, price: 0.32 },
    { description: 'Algorithm review', quantity: 3, price: 99.999 }
  ]
};

console.log(renderDocument(sample));
console.log(`Rendered ${sample.items.length} line items for ${sample.customer}.`);

