const DEFAULT_DOMAIN = 'example.com';

function heading(user) {
  return `# ${user.fullName} (@${user.username})`;
}

function subheading(user) {
  return `## ${user.location} — age ${user.age}`;
}

function occupationSection(occupation) {
  return `**Occupation:** ${occupation}`;
}

function websiteLink(user) {
  const label = user.website.replace(/^https?:\/\//, '');
  return `[${label}](${user.website})`;
}

function hobbyItem(hobby, index) {
  return `${index + 1}. ${hobby}`;
}

function footer(username) {
  const year = new Date().getFullYear();
  return `_© ${year} ${username}_`;
}

function contactLine(username, domain = DEFAULT_DOMAIN) {
  const address = `${username.toLowerCase().replace(/\s+/g, '.')}@${domain}`;
  return `Contact: <${address}>`;
}

function validate(user) {
  const required = ['username', 'fullName', 'location', 'age', 'occupation', 'website'];
  const missing = required.filter((field) => user[field] === undefined || user[field] === '');
  if (missing.length > 0) {
    throw new Error(`Missing profile fields: ${missing.join(', ')}`);
  }
  if (!Array.isArray(user.hobbies)) {
    throw new TypeError(`Expected hobbies to be an array, received ${typeof user.hobbies}`);
  }
}

function profile(user) {
  validate(user);
  const lines = [heading(user), subheading(user), '', occupationSection(user.occupation)];
  lines.push(`**Website:** ${websiteLink(user)}`, '', '### Hobbies');
  user.hobbies.forEach((hobby, index) => {
    lines.push(hobbyItem(hobby, index));
  });
  lines.push('', contactLine(user.username), '', footer(user.username));
  return lines.join('\n');
}

const ada = {
  username: 'ada',
  fullName: 'Ada Lovelace',
  location: 'London, UK',
  age: 36,
  occupation: 'Mathematician',
  website: 'https://ada.dev',
  hobbies: ['Analytical engines', 'Poetry', 'Horse riding'],
};

const card = profile(ada);
console.log(card);
console.log(`--- ${card.split('\n').length} lines rendered for @${ada.username} ---`);

module.exports = { profile, heading, subheading, contactLine, footer };

