function slug(text) {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');
}

function validate(details) {
  const required = ['recipient', 'product', 'discount', 'promoCode', 'expires', 'sender'];
  const missing = required.filter((key) => !details[key]);
  if (missing.length) {
    throw new Error(`Campaign details are incomplete: missing ${missing.join(', ')}`);
  }
  const discount = Number(details.discount);
  if (!Number.isFinite(discount) || discount <= 0 || discount >= 100) {
    throw new Error(`Discount must be between 1 and 99, received ${details.discount}`);
  }
  return discount;
}

function formatExpiry(expires) {
  const date = new Date(expires);
  if (Number.isNaN(date.getTime())) {
    return String(expires);
  }
  const month = date.toLocaleString('en-US', { month: 'long' });
  return `${month} ${date.getDate()}, ${date.getFullYear()}`;
}

function campaign(details) {
  const discount = validate(details);
  const { recipient, product, promoCode, sender } = details;
  const code = promoCode.toUpperCase();
  const deadline = formatExpiry(details.expires);

  const subject = `Save ${discount}% on ${product} — today only!`;
  const greeting = `Hi ${recipient},`;
  const intro = `We thought you would love our ${product}, hand-picked for customers like you.`;
  const offer = `Use promo code ${code} at checkout for ${discount}% off your order.`;
  const urgency = `Hurry — this offer expires on ${deadline}.`;
  const link = `https://shop.example.com/redeem?code=${code}`;
  const cta = `Claim your discount here: ${link}`;
  const signOff = `Warm regards,\n${sender}`;
  const unsubscribe = `https://shop.example.com/unsubscribe?user=${slug(recipient)}`;
  const footer = `Not interested any more? Unsubscribe: ${unsubscribe}`;

  return [subject, greeting, intro, offer, urgency, cta, signOff, footer];
}

function render(lines) {
  const [subject, ...body] = lines;
  const header = `Subject: ${subject}`;
  return [header, '', ...body].join('\n\n');
}

function main() {
  const details = {
    recipient: 'Ada Lovelace',
    product: 'Analytical Engine Toolkit',
    discount: 25,
    promoCode: 'spring25',
    expires: '2026-04-30',
    sender: 'The Example Shop Team'
  };

  const lines = campaign(details);
  console.log(render(lines));
  console.log(`\n(${lines.length} lines generated for ${details.recipient})`);
}

main();

module.exports = { campaign, render, formatExpiry, slug };

