const REQUIRED_FIELDS = [
  'inputFile',
  'outputFile',
  'videoCodec',
  'audioCodec',
  'bitrate',
  'resolution',
  'preset',
];

function validateOptions(options) {
  if (!options || typeof options !== 'object') {
    throw new TypeError(`execute() expects an options object, received ${typeof options}`);
  }
  for (const field of REQUIRED_FIELDS) {
    const value = options[field];
    if (value === undefined || value === null || value === '') {
      throw new Error(`Missing required encoder option "${field}"`);
    }
  }
  return options;
}

function normalizeBitrate(bitrate) {
  if (typeof bitrate === 'number') {
    return `${bitrate}k`;
  }
  const trimmed = String(bitrate).trim();
  return /^\d+$/.test(trimmed) ? `${trimmed}k` : trimmed;
}

function normalizeResolution(resolution) {
  const match = String(resolution).trim().match(/^(\d+)\s*[x:]\s*(\d+)$/i);
  if (!match) {
    throw new Error(`Resolution "${resolution}" is not in WIDTHxHEIGHT form`);
  }
  return `scale=${match[1]}:${match[2]}`;
}

function execute(options) {
  const opts = validateOptions(options);
  const executable = 'ffmpeg';
  const input = `-i ${opts.inputFile}`;
  const videoCodec = `-c:v ${opts.videoCodec}`;
  const audioCodec = `-c:a ${opts.audioCodec}`;
  const bitrate = `-b:v ${normalizeBitrate(opts.bitrate)}`;
  const scale = `-vf ${normalizeResolution(opts.resolution)}`;
  const preset = `-preset ${opts.preset}`;
  const output = `${opts.outputFile}`;
  return [executable, input, videoCodec, audioCodec, bitrate, scale, preset, output];
}

function describeJob(options) {
  const parts = execute(options);
  const command = parts.join(' ');
  return `${options.inputFile} -> ${options.outputFile}\n  ${command}`;
}

function main() {
  const jobs = [
    {
      inputFile: 'clips/raw_footage.mov',
      outputFile: 'renders/raw_footage.mp4',
      videoCodec: 'libx264',
      audioCodec: 'aac',
      bitrate: 4500,
      resolution: '1920x1080',
      preset: 'slow',
    },
    {
      inputFile: 'clips/interview.mkv',
      outputFile: 'renders/interview_720p.mp4',
      videoCodec: 'libx265',
      audioCodec: 'libopus',
      bitrate: '2M',
      resolution: '1280:720',
      preset: 'veryfast',
    },
  ];

  jobs.forEach((job, index) => {
    console.log(`Job ${index + 1}: ${describeJob(job)}`);
  });

  try {
    execute({ ...jobs[0], resolution: 'full-hd' });
  } catch (err) {
    console.log(`Rejected job: ${err.message}`);
  }
}

main();

module.exports = { execute, describeJob };

