function validateBuild(build) {
  const required = ['compiler', 'flags', 'target', 'srcDir', 'objDir', 'installPath'];
  const missing = required.filter((key) => !build[key]);
  if (missing.length > 0) {
    throw new Error(`Incomplete build spec, missing: ${missing.join(', ')}`);
  }
  return build;
}

function normalizeFlags(flags) {
  if (Array.isArray(flags)) {
    return flags.join(' ');
  }
  return String(flags).trim();
}

function makefile(build) {
  const spec = validateBuild(build);
  const flags = normalizeFlags(spec.flags);
  const objectPattern = `${spec.objDir}/%.o`;
  const sourcePattern = `${spec.srcDir}/%.c`;

  const compilerVar = `CC = ${spec.compiler}`;
  const flagsVar = `CFLAGS = ${flags}`;
  const objectsVar = `OBJECTS = $(patsubst ${sourcePattern},${objectPattern},$(wildcard ${sourcePattern}))`;
  const targetRule = `${spec.target}: $(OBJECTS)\n\t$(CC) $(CFLAGS) -o ${spec.target} $(OBJECTS)`;
  const compileRule = `${objectPattern}: ${sourcePattern}\n\t$(CC) $(CFLAGS) -c $< -o $@`;
  const cleanRule = `clean:\n\trm -rf ${spec.objDir}/*.o`;
  const installRule = `install: ${spec.target}\n\tinstall -m 755 ${spec.target} ${spec.installPath}`;
  const uninstallRule = `uninstall:\n\trm -f ${spec.installPath}/${spec.target}`;
  const phonyRule = `.PHONY: clean install uninstall`;

  return [
    compilerVar,
    flagsVar,
    objectsVar,
    targetRule,
    compileRule,
    cleanRule,
    installRule,
    uninstallRule,
    phonyRule
  ];
}

function renderMakefile(build) {
  return `${makefile(build).join('\n\n')}\n`;
}

function describeBuild(build) {
  const flags = normalizeFlags(build.flags);
  const header = `# Build of ${build.target} with ${build.compiler}`;
  const flagLine = `# Flags: ${flags || 'none'}`;
  const layout = `# Sources in ${build.srcDir}, objects in ${build.objDir}`;
  const destination = `# Installs into ${build.installPath}`;
  return [header, flagLine, layout, destination].join('\n');
}

function main() {
  const build = {
    compiler: 'gcc',
    flags: ['-Wall', '-Wextra', '-O2'],
    target: 'myapp',
    srcDir: 'src',
    objDir: 'build/obj',
    installPath: '/usr/local/bin'
  };

  console.log(describeBuild(build));
  console.log(renderMakefile(build));

  const rules = makefile(build);
  console.log(`Generated ${rules.length} makefile sections.`);
}

main();

