const INDENT = '    ';

function validateServer(server) {
  const required = ['domain', 'listenPort', 'upstream', 'logFile', 'sslCert', 'sslKey'];
  const missing = required.filter((key) => !server[key]);
  if (missing.length > 0) {
    throw new Error(`Missing server settings: ${missing.join(', ')}`);
  }
  const port = Number(server.listenPort);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`Invalid listen port: ${server.listenPort}`);
  }
  return { ...server, listenPort: port };
}

function proxy(server) {
  const cfg = validateServer(server);
  const open = `server {`;
  const listen = `${INDENT}listen ${cfg.listenPort} ssl;`;
  const serverName = `${INDENT}server_name ${cfg.domain};`;
  const accessLog = `${INDENT}access_log ${cfg.logFile};`;
  const sslCert = `${INDENT}ssl_certificate ${cfg.sslCert};`;
  const sslKey = `${INDENT}ssl_certificate_key ${cfg.sslKey};`;
  const location = `${INDENT}location / {\n${INDENT.repeat(2)}proxy_pass ${cfg.upstream};`;
  const hostHeader = `${INDENT.repeat(2)}proxy_set_header Host ${cfg.domain};`;
  return [open, listen, serverName, accessLog, sslCert, sslKey, location, hostHeader];
}

function renderConfig(server) {
  const lines = proxy(server);
  const body = lines.join('\n');
  return `${body}\n${INDENT}}\n}`;
}

