function capitalize(word) {
  const head = word.charAt(0).toUpperCase();
  return head + word.slice(1);
}

function groupHeader(app, metric) {
  const scope = app + '_' + metric;
  const groupName = `  - name: ${scope}_rules`;
  const interval = `    interval: ${metric === 'memory' ? '30s' : '1m'}`;
  const rules = '    rules:';
  return [groupName, interval, rules].join('\n');
}

function selectorFor(metric, app) {
  const series = metric + '_usage_percent';
  return `${series}{app="${app}"}`;
}

function warningAlert(def) {
  const { metric, warning, app } = def;
  const name = app + 'High' + capitalize(metric) + 'Warning';
  const alertName = `      - alert: ${name}`;
  const condition = selectorFor(metric, app) + ' > ' + warning;
  const expr = `        expr: ${condition}`;
  const duration = '        for: 5m';
  const labelsOpen = '        labels:';
  const severity = '          severity: warning';
  const appLabel = `          app: ${app}`;
  const annotations = '        annotations:';
  const text = metric + ' above ' + warning + '% on ' + app;
  const summary = `          summary: "${text}"`;
  return [alertName, expr, duration, labelsOpen, severity, appLabel, annotations, summary].join('\n');
}

function criticalAlert(def) {
  const { metric, critical, app } = def;
  const name = app + 'High' + capitalize(metric) + 'Critical';
  const alertName = `      - alert: ${name}`;
  const condition = selectorFor(metric, app) + ' > ' + critical;
  const expr = `        expr: ${condition}`;
  const duration = '        for: 2m';
  const labelsOpen = '        labels:';
  const severity = '          severity: critical';
  const appLabel = `          app: ${app}`;
  const annotations = '        annotations:';
  const headline = metric + ' critically high on ' + app;
  const summary = `          summary: "${headline}"`;
  const detail = metric + ' exceeded ' + critical + '% for 2 minutes';
  const description = `          description: "${detail}"`;
  return [alertName, expr, duration, labelsOpen, severity, appLabel, annotations, summary, description].join('\n');
}

function validate(def, index) {
  const label = `definition ${index}`;
  if (!def.metric || !def.app) {
    throw new Error(label + ' is missing a metric name or app identifier');
  }
  if (Number(def.warning) >= Number(def.critical)) {
    const bound = `warning ${def.warning} must be below critical ` + def.critical;
    throw new Error(label + ': ' + bound);
  }
}

function alerts(thresholds) {
  const blocks = thresholds.map((def, index) => {
    validate(def, index);
    const header = groupHeader(def.app, def.metric);
    const warn = warningAlert(def);
    const crit = criticalAlert(def);
    return [header, warn, crit].join('\n');
  });
  return `groups:\n${blocks.join('\n')}`;
}

function main() {
  const thresholds = [
    { metric: 'memory', warning: 80, critical: 90, app: 'backend' },
    { metric: 'cpu', warning: 70, critical: 85, app: 'worker' },
  ];
  console.log(alerts(thresholds));
  console.log(`# generated ${thresholds.length} rule group(s)`);
}

main();

module.exports = { alerts, groupHeader, warningAlert, criticalAlert };

