const SITE_ORIGIN = 'https://www.example.com';
const SITEMAP_NS = 'http://www.sitemaps.org/schemas/sitemap/0.9';
const FREQUENCIES = ['always', 'hourly', 'daily', 'weekly', 'monthly', 'yearly', 'never'];

function xmlDeclaration(encoding = 'UTF-8') {
  return `<?xml version="1.0" encoding="${encoding}"?>`;
}

function urlSetOpenTag() {
  return `<urlset xmlns="${SITEMAP_NS}">`;
}

function urlSetCloseTag() {
  return '</urlset>';
}

function normalizePath(path) {
  if (typeof path !== 'string' || path.length === 0) {
    throw new TypeError(`Invalid page path: ${JSON.stringify(path)}`);
  }
  return path.startsWith('/') ? path : `/${path}`;
}

function locationTag(path) {
  return `    <loc>${SITE_ORIGIN}${normalizePath(path)}</loc>`;
}

function priorityTag(priority) {
  const value = Number(priority);
  if (!Number.isFinite(value) || value < 0 || value > 1) {
    throw new RangeError(`Priority must be between 0.0 and 1.0, got ${priority}`);
  }
  return `    <priority>${value.toFixed(1)}</priority>`;
}

function changeFrequencyTag(frequency) {
  if (!FREQUENCIES.includes(frequency)) {
    throw new RangeError(`Unknown change frequency "${frequency}", expected one of ${FREQUENCIES.join(', ')}`);
  }
  return `    <changefreq>${frequency}</changefreq>`;
}

function lastModifiedTag(date = new Date()) {
  return `    <lastmod>${date.toISOString().slice(0, 10)}</lastmod>`;
}

function urlEntry(page) {
  return [
    '  <url>',
    locationTag(page.path),
    priorityTag(page.priority),
    changeFrequencyTag(page.changefreq),
    lastModifiedTag(page.lastmod ? new Date(page.lastmod) : undefined),
    '  </url>',
  ].join('\n');
}

function sitemap(pages) {
  if (!Array.isArray(pages)) {
    throw new TypeError(`sitemap() expects an array of pages, received ${typeof pages}`);
  }
  return [xmlDeclaration(), urlSetOpenTag(), ...pages.map(urlEntry), urlSetCloseTag()].join('\n');
}

const pages = [
  { path: '/', priority: 1.0, changefreq: 'daily', lastmod: '2026-09-18' },
  { path: 'contact', priority: 0.6, changefreq: 'monthly', lastmod: '2026-09-18' },
];

console.log(sitemap(pages));

module.exports = { sitemap, xmlDeclaration, urlSetOpenTag, urlSetCloseTag, urlEntry };

