const CRLF = "\r\n";

function beginTags() {
  const begin = "BEGIN:VCARD";
  const version = "VERSION:3.0";
  return [begin, version];
}

function normalizeName(part) {
  const trimmed = String(part).trim();
  if (!trimmed) {
    throw new Error(`Name parts must not be empty, got "${part}"`);
  }
  return trimmed.charAt(0).toUpperCase() + trimmed.slice(1);
}

function nameProperties(firstName, lastName) {
  const first = normalizeName(firstName);
  const last = normalizeName(lastName);
  const display = [first, last].join(" ");
  const fullName = `FN:${display}`;
  const structured = `N:${[last, first].join(";")};;;`;
  return [fullName, structured];
}

function telProperties(phone) {
  const digits = String(phone).replace(/[^\d+]/g, "");
  if (digits.length < 7) {
    throw new Error(`Phone number "${phone}" is too short to be dialled`);
  }
  const work = `TEL;TYPE=WORK,VOICE:${digits}`;
  const home = `TEL;TYPE=HOME,VOICE:${digits}`;
  return [work, home];
}

function emailProperty(email) {
  const address = String(email).trim().toLowerCase();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(address)) {
    throw new Error(`"${email}" is not a valid email address`);
  }
  return `EMAIL;TYPE=INTERNET:${address}`;
}

function orgProperty(organization) {
  const name = String(organization).trim().replace(/,/g, "\\,");
  return `ORG:${name}`;
}

function endTag() {
  return "END:VCARD";
}

function contacts(people) {
  const cards = people.map((person) => {
    const lines = [
      ...beginTags(),
      ...nameProperties(person.firstName, person.lastName),
      ...telProperties(person.phone),
      emailProperty(person.email),
      orgProperty(person.organization),
      endTag(),
    ];
    return lines.join(CRLF);
  });
  return cards.join(CRLF) + CRLF;
}

const directory = [
  {
    firstName: "john",
    lastName: "doe",
    phone: "(555) 123-4567",
    email: "John.Doe@Factory.example",
    organization: "Factory, Inc.",
  },
];

console.log(`Generated ${directory.length} contact card(s):`);
console.log(contacts(directory));

