'use strict';

const DIAGRAM_START = 'sequenceDiagram';
const SOLID_ARROW = '->>';
const DOTTED_ARROW = '-->>';

function join(...parts) {
  return parts.join('');
}

function indent(text) {
  return `    ${text}`;
}

function alias(name) {
  return name.replace(/[^A-Za-z0-9]+/g, '_');
}

function classify(name) {
  const key = name.toLowerCase();
  if (/db|database|store|log/.test(key)) return 'database';
  if (/client|user|customer/.test(key)) return 'actor';
  return 'participant';
}

function startTag(title) {
  const heading = `title ${title}`;
  return [DIAGRAM_START, indent(heading)];
}

function participantLine(name) {
  const declaration = join(classify(name), ' ', alias(name));
  const label = `as ${name}`;
  return indent(join(declaration, ' ', label));
}

function arrowFor(synchronous) {
  return synchronous ? SOLID_ARROW : DOTTED_ARROW;
}

function messageLabel(interaction) {
  const mode = interaction.synchronous ? 'sync' : 'async';
  return join(interaction.message, ` (${mode})`);
}

function messageLine(interaction) {
  const hop = join(alias(interaction.sender), arrowFor(interaction.synchronous), alias(interaction.receiver));
  const label = `: ${messageLabel(interaction)}`;
  return indent(join(hop, label));
}

function activationBlock(interaction) {
  const target = alias(interaction.receiver);
  const open = `activate ${target}`;
  const close = `deactivate ${target}`;
  return [indent(open), messageLine(interaction), indent(close)];
}

function endTag(interactions) {
  const footer = `%% end of diagram (${interactions.length} interactions)`;
  return indent(footer);
}

function diagram(interactions, title = 'Sequence Diagram') {
  const lines = startTag(title);
  const seen = [];
  interactions.forEach((interaction, index) => {
    const { sender, receiver, message } = interaction;
    if (!sender || !receiver || !message) {
      const location = `interaction #${index + 1}`;
      throw new Error(join('Cannot render ', location, ': sender, receiver and message are required'));
    }
    [sender, receiver].forEach((name) => {
      if (!seen.includes(name)) seen.push(name);
    });
  });
  seen.forEach((name) => lines.push(participantLine(name)));
  interactions.forEach((interaction) => {
    if (interaction.synchronous) {
      lines.push(...activationBlock(interaction));
    } else {
      lines.push(messageLine(interaction));
    }
  });
  lines.push(endTag(interactions));
  return lines.join('\n');
}

const calls = [
  { sender: 'Client', receiver: 'Server', message: 'GET /orders', synchronous: true },
  { sender: 'Server', receiver: 'Audit Log', message: 'write access entry', synchronous: false },
];

console.log(diagram(calls, 'Order lookup'));

