function validateConfig(config) {
  const required = ['description', 'execStart', 'workingDirectory', 'user', 'environmentFile'];
  const missing = required.filter((key) => !config || !config[key]);
  if (missing.length > 0) {
    throw new Error(`Incomplete service configuration: missing ${missing.join(', ')}`);
  }
  if (!config.execStart.startsWith('/')) {
    throw new Error(`ExecStart must be an absolute path, got "${config.execStart}"`);
  }
  if (!config.workingDirectory.startsWith('/')) {
    throw new Error(`WorkingDirectory must be an absolute path, got "${config.workingDirectory}"`);
  }
}

function unitSection(config) {
  const header = '[Unit]';
  const descriptionLine = `Description=${config.description}`;
  const afterLine = `After=${config.after || 'network.target'}`;
  return [header, descriptionLine, afterLine];
}

function serviceSection(config) {
  const header = '[Service]';
  const execStartLine = `ExecStart=${config.execStart}`;
  const workingDirectoryLine = `WorkingDirectory=${config.workingDirectory}`;
  const userLine = `User=${config.user}`;
  const environmentFileLine = `EnvironmentFile=${config.environmentFile}`;
  const restartLine = `Restart=${config.restart || 'always'}`;
  return [header, execStartLine, workingDirectoryLine, userLine, environmentFileLine, restartLine];
}

function installSection(config) {
  const header = '[Install]';
  const wantedByLine = `WantedBy=${config.wantedBy || 'multi-user.target'}`;
  return [header, wantedByLine];
}

function service(config) {
  validateConfig(config);
  const blocks = [unitSection(config), serviceSection(config), installSection(config)];
  return blocks.map((lines) => `${lines.join('\n')}\n`).join('\n');
}

function unitFileName(config) {
  const base = config.name || config.description.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return `${base.replace(/^-+|-+$/g, '')}.service`;
}

function main() {
  const appConfig = {
    name: 'inventory-api',
    description: 'Inventory API (Node.js)',
    execStart: '/usr/bin/node /srv/inventory-api/server.js',
    workingDirectory: '/srv/inventory-api',
    user: 'inventory',
    environmentFile: '/etc/inventory-api/env'
  };

  const fileName = unitFileName(appConfig);
  const unitFile = service(appConfig);

  console.log(`# /etc/systemd/system/${fileName}`);
  console.log(unitFile);
  console.log(`# enable with: systemctl enable --now ${fileName}`);

  try {
    service({ ...appConfig, execStart: 'node server.js' });
  } catch (error) {
    console.error(`Rejected configuration: ${error.message}`);
  }
}

main();

module.exports = { service, unitSection, serviceSection, installSection, unitFileName };

