  const wantedByLine = 'WantedBy=' + (config.wantedBy || 'multi-user.target');
  return [header, wantedByLine];
}

function service(config) {
  validateConfig(config);
  const blocks = [unitSection(config), serviceSection(config), installSection(config)];
  return blocks.map((lines) => lines.join('\n') + '\n').join('\n');
}

function unitFileName(config) {
  const base = config.name || config.description.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  return base.replace(/^-+|-+$/g, '') + '.service';
}

function main() {
  const appConfig = {
    name: 'inventory-api',
    description: 'Inventory API (Node.js)',
    execStart: '/usr/bin/node /srv/inventory-api/server.js',
    workingDirectory: '/srv/inventory-api',
    user: 'inventory',
    environmentFile: '/etc/inventory-api/env'
  };

  const fileName = unitFileName(appConfig);
  const unitFile = service(appConfig);

  console.log('# /etc/systemd/system/' + fileName);
  console.log(unitFile);
  console.log('# enable with: systemctl enable --now ' + fileName);

  try {
    service({ ...appConfig, execStart: 'node server.js' });
  } catch (error) {
    console.error('Rejected configuration: ' + error.message);
  }
}

main();

module.exports = { service, unitSection, serviceSection, installSection, unitFileName };

