const LOG_DIR = '/var/log/apache2';
const DEFAULT_PORT = 80;

function validateDomain(domain) {
  for (const field of ['serverName', 'documentRoot', 'adminEmail']) {
    if (!domain[field]) {
      throw new Error(`Domain is missing the required field "${field}"`);
    }
  }
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(domain.adminEmail)) {
    throw new Error(`Invalid admin email: ${domain.adminEmail}`);
  }
  return {
    serverName: domain.serverName,
    aliases: domain.aliases || [],
    documentRoot: domain.documentRoot.replace(/\/+$/, ''),
    adminEmail: domain.adminEmail,
    port: domain.port || DEFAULT_PORT,
    override: domain.override || 'All'
  };
}

function slugify(serverName) {
  return serverName.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
}

function indent(line) {
  return `    ${line}`;
}

function openingTag(port) {
  return `<VirtualHost *:${port}>`;
}

function portBinding(port) {
  return `Listen ${port}`;
}

function serverNameLine(serverName) {
  return `ServerName ${serverName}`;
}

function serverAliasLine(aliases) {
  return `ServerAlias ${aliases.join(' ')}`;
}

function serverAdminLine(adminEmail) {
  return `ServerAdmin ${adminEmail}`;
}

function documentRootLine(documentRoot) {
  return `DocumentRoot "${documentRoot}"`;
}

function directoryBlock(documentRoot, override) {
  const overrideLine = `AllowOverride ${override}`;
  return [
    `<Directory "${documentRoot}">`,
    indent(overrideLine),
    indent('Options Indexes FollowSymLinks'),
    indent('Require all granted'),
    '</Directory>'
  ];
}

function logPath(fileName) {
  return `${LOG_DIR}/${fileName}`;
}

function errorLogLine(slug) {
  const fileName = `${slug}-error.log`;
  return `ErrorLog ${logPath(fileName)}`;
}

function customLogLine(slug) {
  const fileName = `${slug}-access.log`;
  return `CustomLog ${logPath(fileName)} combined`;
}

function vhost(domain) {
  const config = validateDomain(domain);
  const slug = slugify(config.serverName);
  const lines = [`# Virtual host configuration for ${config.serverName}`];
  lines.push(portBinding(config.port), '', openingTag(config.port));
  lines.push(indent(serverNameLine(config.serverName)));
  if (config.aliases.length > 0) {
    lines.push(indent(serverAliasLine(config.aliases)));
  }
  lines.push(indent(serverAdminLine(config.adminEmail)));
  lines.push(indent(documentRootLine(config.documentRoot)));
  for (const line of directoryBlock(config.documentRoot, config.override)) {
    lines.push(indent(line));
  }
  lines.push(indent(errorLogLine(slug)));
  lines.push(indent(customLogLine(slug)));
  lines.push('</VirtualHost>');
  return lines.join('\n');
}

console.log(vhost({
  serverName: 'example.com',
  aliases: ['www.example.com'],
  documentRoot: '/var/www/example.com/public/',
  adminEmail: 'admin@example.com'
}));

module.exports = { vhost, slugify, directoryBlock, errorLogLine, customLogLine };

