function parseEnvironment(environment) {
  const [os = 'Unknown', browser = 'Unknown'] = environment.split('/').map((part) => part.trim());
  const [browserName, browserVersion = 'unspecified'] = browser.split(/\s+(?=[\d.]+$)/);
  return { os, browserName, browserVersion };
}

function buildHeader(issue) {
  const heading = `# ${issue.title}`;
  const reporterLine = `**Reported by:** ${issue.reporter}`;
  return [heading, '', reporterLine, ''].join('\n');
}

function buildEnvironmentTable(environment) {
  const { os, browserName, browserVersion } = parseEnvironment(environment);
  const osRow = `| Operating system | ${os} |`;
  const browserRow = `| Browser | ${browserName} ${browserVersion} |`;
  return ['## Environment', '', '| Item | Value |', '| --- | --- |', osRow, browserRow, ''].join('\n');
}

function buildSteps(steps) {
  const stepsHeader = `## Steps to reproduce (${steps.length})`;
  return [stepsHeader, '', ...steps.map((step, index) => `${index + 1}. ${step}`), ''].join('\n');
}

function buildConclusion(issue) {
  const expectedBlock = `> ${issue.expected}`;
  const actualBlock = `> ${issue.actual || 'Not as expected — see the steps above.'}`;
  return [
    '## Expected behavior',
    '',
    expectedBlock,
    '',
    '## Actual behavior',
    '',
    actualBlock,
    '',
  ].join('\n');
}

function ticket(issue) {
  if (!issue || !issue.title) {
    throw new Error('A ticket requires a title.');
  }
  if (!Array.isArray(issue.steps) || issue.steps.length === 0) {
    throw new Error(`Ticket "${issue.title}" needs at least one reproduction step.`);
  }
  const sections = [
    buildHeader(issue),
    buildEnvironmentTable(issue.environment || 'Unknown / Unknown'),
    buildSteps(issue.steps),
    buildConclusion(issue),
  ];
  return sections.join('\n');
}

const loginBug = {
  title: 'Login fails silently after password reset',
  environment: 'Windows 11 / Chrome 120.0.6099',
  reporter: 'Dana Reyes (administrator)',
  steps: [
    'Request a password reset from the login page.',
    'Follow the emailed link and set a new password.',
    'Return to the login page and sign in with the new password.',
  ],
  expected: 'The user is signed in and redirected to the dashboard.',
  actual: 'The page reloads with an empty form and no error message.',
};

console.log(ticket(loginBug));

module.exports = { ticket, buildHeader, buildEnvironmentTable, buildSteps, buildConclusion, parseEnvironment };

