const IPTABLES = 'iptables';

function shebang(interpreter = '/bin/sh') {
  return `#!${interpreter}`;
}

function flushCommand() {
  return `${IPTABLES} -F`;
}

function defaultPolicies() {
  const inputDrop = `${IPTABLES} -P INPUT DROP`;
  const forwardDrop = `${IPTABLES} -P FORWARD DROP`;
  const outputAccept = `${IPTABLES} -P OUTPUT ACCEPT`;
  return [inputDrop, forwardDrop, outputAccept];
}

function loopbackRule() {
  return `${IPTABLES} -A INPUT -i lo -j ACCEPT`;
}

function validatePolicy(policy, index) {
  const where = `policy #${index + 1}`;
  if (!policy.protocol) {
    throw new Error(`${where} is missing a protocol`);
  }
  const port = Number(policy.port);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    throw new Error(`${where} has an invalid port: ${policy.port}`);
  }
  if (!policy.source) {
    throw new Error(`${where} is missing a source ip range`);
  }
  const action = String(policy.action).toUpperCase();
  if (action !== 'ACCEPT' && action !== 'DROP') {
    throw new Error(`${where} has an unsupported action: ${policy.action}`);
  }
  return { protocol: String(policy.protocol).toLowerCase(), port, source: policy.source, action };
}

function portRule(policy, index) {
  const { protocol, port, source, action } = validatePolicy(policy, index);
  const protocolFlag = `-p ${protocol}`;
  const sourceFlag = `-s ${source}`;
  const portFlag = `--dport ${port}`;
  const jumpFlag = `-j ${action}`;
  return `${IPTABLES} -A INPUT ${protocolFlag} ${sourceFlag} ${portFlag} ${jumpFlag}`;
}

function firewall(policies) {
  if (!Array.isArray(policies)) {
    throw new TypeError(`policies must be an array, received ${typeof policies}`);
  }
  const lines = [shebang(), '', flushCommand(), ...defaultPolicies(), loopbackRule()];
  policies.forEach((policy, index) => {
    lines.push(portRule(policy, index));
  });
  return `${lines.join('\n')}\n`;
}

function summarize(policies) {
  const opened = policies
    .filter((policy) => String(policy.action).toUpperCase() === 'ACCEPT')
    .map((policy) => `${policy.protocol}/${policy.port}`);
  return `Generated ruleset with ${policies.length} policies, open: ${opened.join(', ')}`;
}

const localPolicies = [
  { protocol: 'tcp', port: 22, source: '192.168.1.0/24', action: 'accept' },
  { protocol: 'tcp', port: 443, source: '0.0.0.0/0', action: 'accept' },
  { protocol: 'udp', port: 161, source: '10.0.0.0/8', action: 'drop' },
];

const script = firewall(localPolicies);
console.log(script);
console.log(`# ${summarize(localPolicies)}`);

module.exports = { firewall, portRule, flushCommand, defaultPolicies, loopbackRule, shebang };

