const INDENT = '  ';

function indentLine(depth, text) {
  return INDENT.repeat(depth) + text;
}

function formatLiteral(value) {
  if (typeof value === 'string') {
    return `"${value}"`;
  }
  return String(value);
}

function fieldPath(field) {
  return `"$${field}"`;
}

function validateQuery(query) {
  for (const key of ['collection', 'groupBy', 'sumAlias']) {
    if (!query[key]) {
      throw new TypeError(`Query is missing the required property "${key}".`);
    }
