const NEWLINE = '\n';
const FIELD_NAMES = ['minute', 'hour', 'day', 'month', 'weekday'];
const FIELD_PATTERN = /^[0-9*/,\-]+$/;

const DEFAULT_ENVIRONMENT = {
  shell: '/bin/sh',
  path: '/usr/local/bin:/usr/bin:/bin',
  mailto: 'root'
};

function environmentHeader(environment) {
  const shellAssignment = `SHELL=${environment.shell}`;
  const pathAssignment = `PATH=${environment.path}`;
  const mailAssignment = `MAILTO=${environment.mailto}`;
  return [shellAssignment, pathAssignment, mailAssignment].join(NEWLINE);
}

function timingColumns(task) {
  if (task.special) {
    return `@${task.special}`;
  }
  const columns = FIELD_NAMES.map(name => {
    const expression = task[name] === undefined ? '*' : String(task[name]);
    if (!FIELD_PATTERN.test(expression)) {
      throw new Error(`invalid schedule expression: ${expression}`);
    }
    return expression;
  });
  return columns.join(' ');
}

function commandInvocation(task) {
  const parts = [];
  if (task.workdir) {
    parts.push(`cd ${task.workdir} &&`);
  }
  if (task.interpreter) {
    parts.push(task.interpreter);
  }
  parts.push(task.command);
  return parts.join(' ');
}

function outputRedirection(task) {
  const standardOutput = `>> ${task.log}`;
  const errorOutput = task.errorLog ? `2>> ${task.errorLog}` : '2>&1';
  return [standardOutput, errorOutput].join(' ');
}

function taskEntry(task, index) {
  if (!task.command) {
    throw new Error(`task #${index + 1} has no command to execute`);
  }
  if (!task.log) {
    throw new Error(`task #${index + 1} has no output log file`);
  }
  const description = task.description || `run ${task.command}`;
  const comment = `# ${description}`;
  const columns = [timingColumns(task), commandInvocation(task), outputRedirection(task)];
  return [comment, columns.join(' ')].join(NEWLINE);
}

function schedule(tasks) {
  const banner = `# generated schedule file with ${tasks.length} task(s)`;
  const blocks = [banner, environmentHeader(DEFAULT_ENVIRONMENT)];
  tasks.forEach((task, index) => blocks.push(taskEntry(task, index)));
  return blocks.join(NEWLINE + NEWLINE) + NEWLINE;
}

const nightlyTasks = [
  {
    minute: 0,
    hour: 0,
    description: 'daily cleanup of temporary files',
    workdir: '/srv/app',
    interpreter: '/bin/sh',
    command: 'scripts/cleanup.sh',
    log: '/var/log/cleanup.log',
    errorLog: '/var/log/cleanup.err'
  },
  {
    minute: '*/15',
    hour: '9-17',
    weekday: '1-5',
    command: '/usr/bin/report --hourly',
    log: '/var/log/report.log'
  }
];

process.stdout.write(schedule(nightlyTasks));

