const LOOPBACK = '127.0.0.1/8';
const DEFAULT_PORTS = { ssh: 'ssh', 'nginx-http-auth': 'http,https', postfix: 'smtp,submission' };

function validateConfig(config, index) {
  const required = ['service', 'enabled', 'filter', 'logPath', 'maxRetry', 'findTime', 'banTime'];
  const missing = required.filter((key) => config[key] === undefined || config[key] === null);
  if (missing.length > 0) {
    throw new Error(`Configuration #${index} is missing: ${missing.join(', ')}`);
  }
  if (!Number.isInteger(config.maxRetry) || config.maxRetry < 1) {
    throw new Error(`Configuration "${config.service}" needs a positive integer maxRetry`);
  }
  return config;
}

function resolvePort(config) {
  if (config.port !== undefined) {
    return String(config.port);
  }
  return DEFAULT_PORTS[config.service] || config.service;
}

function actionDirective(config) {
  const port = resolvePort(config);
  return `action = iptables[name=${config.service}, port=${port}, protocol=tcp]`;
}

function jail(configs) {
  const blocks = configs.map((config, index) => {
    validateConfig(config, index);
    const lines = [];
    lines.push(`[${config.service}]`);
    lines.push(`enabled = ${config.enabled ? 'true' : 'false'}`);
    lines.push(`filter = ${config.filter}`);
    lines.push(actionDirective(config));
    lines.push(`logpath = ${config.logPath}`);
    lines.push(`maxretry = ${config.maxRetry}`);
    lines.push(`findtime = ${config.findTime}`);
    lines.push(`bantime = ${config.banTime}`);
    lines.push(`ignoreip = ${LOOPBACK}`);
    return lines.join('\n');
  });
  return blocks.map((block) => `${block}\n`).join('\n');
}

function summarize(configs) {
  const active = configs.filter((config) => config.enabled);
  const names = active.map((config) => config.service).join(', ');
  return `# ${active.length} of ${configs.length} jails enabled: ${names}`;
}

function main() {
  const configs = [
    {
      service: 'ssh',
      enabled: true,
      filter: 'sshd',
      logPath: '/var/log/auth.log',
      maxRetry: 5,
      findTime: 600,
      banTime: 3600,
    },
    {
      service: 'nginx-http-auth',
      enabled: false,
      filter: 'nginx-http-auth',
      logPath: '/var/log/nginx/error.log',
      maxRetry: 3,
      findTime: 300,
      banTime: 86400,
    },
  ];
  console.log(summarize(configs));
  console.log(jail(configs));
}

main();

