const KML_NS = 'http://www.opengis.net/kml/2.2';

function formatCoordinate(value, precision = 6) {
  const num = Number(value);
  if (!Number.isFinite(num)) {
    throw new TypeError(`Coordinate value is not a finite number: ${value}`);
  }
  return num.toFixed(precision).replace(/\.?0+$/, '');
}

function escapeXml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function validateWaypoint(waypoint, index) {
  if (!waypoint || typeof waypoint !== 'object') {
    throw new TypeError(`Waypoint at index ${index} must be an object`);
  }
  const lat = Number(waypoint.latitude);
  const lon = Number(waypoint.longitude);
  if (!(lat >= -90 && lat <= 90)) {
    throw new RangeError(`Latitude out of range for "${waypoint.name}"`);
  }
  if (!(lon >= -180 && lon <= 180)) {
    throw new RangeError(`Longitude out of range for "${waypoint.name}"`);
  }
  return { ...waypoint, latitude: lat, longitude: lon, altitude: Number(waypoint.altitude) || 0 };
}

function coordinateString({ latitude, longitude, altitude }) {
  const lon = formatCoordinate(longitude);
  const lat = formatCoordinate(latitude);
  return `${lon},${lat},${formatCoordinate(altitude, 1)}`;
}

function placemark(waypoint, indent) {
  const pad = ' '.repeat(indent);
  const inner = ' '.repeat(indent + 2);
  const deep = ' '.repeat(indent + 4);
  const lines = [`${pad}<Placemark>`];
  lines.push(`${inner}<name>${escapeXml(waypoint.name)}</name>`);
  lines.push(`${inner}<description>${escapeXml(waypoint.description)}</description>`);
  lines.push(`${inner}<Point>`);
  lines.push(`${deep}<coordinates>${coordinateString(waypoint)}</coordinates>`);
  lines.push(`${inner}</Point>`);
  lines.push(`${pad}</Placemark>`);
  return lines.join('\n');
}

function track(waypoints) {
  const list = Array.isArray(waypoints) ? waypoints : [waypoints];
  const lines = ['<?xml version="1.0" encoding="UTF-8"?>'];
  lines.push(`<kml xmlns="${KML_NS}">`);
  lines.push('  <Document>');
  list.map(validateWaypoint).forEach((waypoint) => {
    lines.push(placemark(waypoint, 4));
  });
  lines.push('  </Document>');
  lines.push('</kml>');
  return `${lines.join('\n')}\n`;
}

function main() {
  const waypoints = [
    { name: 'Paris', description: 'Capital of France', latitude: 48.856614, longitude: 2.352222, altitude: 35 },
    { name: 'Berlin', description: 'Capital of Germany', latitude: 52.520008, longitude: 13.404954, altitude: 34 },
  ];
  const document = track(waypoints);
  process.stdout.write(document);
  process.stdout.write(`<!-- ${waypoints.length} placemarks written -->\n`);
}

if (require.main === module) {
  main();
}

