function assertPresent(value, label) {
  if (value === undefined || value === null || `${value}`.trim() === '') {
    throw new Error(`Missing required configuration value: ${label}`);
  }
  return value;
}

function validatePort(port, label) {
  const parsed = Number(port);
  if (!Number.isInteger(parsed) || parsed < 1 || parsed > 65535) {
    throw new Error(`${label} must be an integer between 1 and 65535, got "${port}"`);
  }
  return parsed;
}

function formatEndpoint(host, port) {
  assertPresent(host, 'peer endpoint host');
  return `${host}:${validatePort(port, 'Endpoint port')}`;
}

function interfaceSection(config) {
  const lines = ['[Interface]'];
  lines.push(`PrivateKey = ${assertPresent(config.privateKey, 'privateKey')}`);
  lines.push(`Address = ${assertPresent(config.address, 'address')}`);
  lines.push(`ListenPort = ${validatePort(config.listenPort, 'ListenPort')}`);
  lines.push(`DNS = ${assertPresent(config.dns, 'dns')}`);
  lines.push(`MTU = ${assertPresent(config.mtu, 'mtu')}`);
  return lines;
}

function peerSection(peer, index) {
  const label = `peers[${index}]`;
  if (!peer || typeof peer !== 'object') {
    throw new TypeError(`${label} must be a peer object`);
  }
  const publicKey = assertPresent(peer.publicKey, label + '.publicKey');
  const allowedIps = assertPresent(peer.allowedIps, label + '.allowedIps');
  const keepalive = assertPresent(peer.keepalive, label + '.keepalive');
  const lines = ['[Peer]', ''];
  lines.push(`PublicKey = ${publicKey}`);
  lines.push(`AllowedIPs = ${allowedIps}`);
  lines.push(`Endpoint = ${formatEndpoint(peer.endpointHost, peer.endpointPort)}`);
  lines.push(`PersistentKeepalive = ${keepalive}`);
  return lines;
}

function tunnel(config) {
  if (!config || typeof config !== 'object') {
    throw new TypeError(`tunnel() expects a configuration object, received ${typeof config}`);
  }
  const peers = Array.isArray(config.peers) ? config.peers : [];
  const lines = interfaceSection(config);
  peers.forEach((peer, index) => {
    lines.push(...peerSection(peer, index));
  });
  return lines.join('\n');
}

module.exports = { tunnel, formatEndpoint };

