const BATCH_TAG = '%echo Generating a';
const REQUIRED_FIELDS = ['keyType', 'keyLength', 'expire', 'realName', 'email'];

function normalizeLength(value, label) {
  const length = Number(value);
  if (!Number.isInteger(length) || length < 1024) {
    throw new Error(`The key length for ${label} must be a whole number of at least 1024 bits`);
  }
  return length;
}

function validateProfile(profile, index) {
  const label = `profile #${index + 1}`;
  for (const field of REQUIRED_FIELDS) {
    if (profile[field] === undefined || profile[field] === '') {
      throw new Error(`Missing required field "${field}" in ${label}`);
    }
  }
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(profile.email)) {
    throw new Error(`Invalid email address in ${label}`);
  }
  return { label, keyLength: normalizeLength(profile.keyLength, label) };
}

function buildBlock(profile, keyLength) {
  const lines = [`${BATCH_TAG} ${profile.keyType} key`];
  lines.push(`Key-Type: ${profile.keyType}`);
  lines.push(`Key-Length: ${keyLength}`);
  lines.push(`Subkey-Type: ${profile.keyType}`);
  lines.push(`Subkey-Length: ${keyLength}`);
  lines.push(`Name-Real: ${profile.realName}`);
  lines.push(`Name-Email: ${profile.email}`);
  lines.push(`Expire-Date: ${profile.expire}`);
  if (profile.passphrase) {
    lines.push(`Passphrase: ${profile.passphrase}`);
  }
  lines.push('%commit');
  return lines.join('\n');
}

function encryption(profiles) {
  return profiles
    .map((profile, index) => {
      const { keyLength } = validateProfile(profile, index);
      return buildBlock(profile, keyLength);
    })
    .join('\n\n');
}

function formatIdentity(profile) {
  const address = `<${profile.email}>`;
  return `${profile.realName} ${address}`;
}

function manifest(profiles) {
  return profiles
    .map((profile, index) => {
      const position = `${index + 1}.`;
      const bits = `${profile.keyLength} bits,`;
      const expiry = `expires in ${profile.expire},`;
      const protection = profile.passphrase ? 'passphrase protected' : 'unprotected';
      return [position, formatIdentity(profile), profile.keyType, bits, expiry, protection].join(' ');
    })
    .join('\n');
}

const profiles = [
  { keyType: 'RSA', keyLength: 4096, expire: '2y', realName: 'Ada Lovelace', email: 'ada@example.org', passphrase: 'analytical-engine' },
  { keyType: 'RSA', keyLength: 2048, expire: '6m', realName: 'Alan Turing', email: 'alan@example.org' },
  { keyType: 'DSA', keyLength: 3072, expire: '0', realName: 'Grace Hopper', email: 'grace@example.org', passphrase: 'nanoseconds' },
];

const script = encryption(profiles);
console.log(script);
console.log(`\nKeys queued for generation:\n${manifest(profiles)}`);

module.exports = { encryption, buildBlock, manifest, formatIdentity };

