function formatHeader(version) {
  return `#EXTM3U version=${version}`;
}

function formatDescription(title, creator, exportDate) {
  const credit = `${title} by ${creator}`;
  return `# ${credit}, exported ${exportDate}`;
}

function formatGlobalTag(genre) {
  return `#EXTGENRE:${genre}`;
}

function formatRuntime(track) {
  const label = `${track.artist} - ${track.title}`;
  return `#EXTINF:${track.duration},${label}`;
}

function formatPath(track) {
  const fileName = `${track.file}.${track.extension}`;
  return `${track.folder}/${fileName}`;
}

function formatTrackTag(track) {
  const size = `${track.sizeMb.toFixed(1)}MB`;
  return `#EXTTAG:size=${size} bitrate=${track.bitrate}kbps`;
}

function totalDuration(tracks) {
  return tracks.reduce((sum, track) => sum + track.duration, 0);
}

function generate(playlist) {
  const tracks = playlist.tracks || [];
  const lines = [formatHeader(playlist.version)];
  lines.push(formatDescription(playlist.title, playlist.creator, playlist.exportDate));
  lines.push(formatGlobalTag(playlist.genre));

  for (const track of tracks) {
    lines.push(formatRuntime(track));
    lines.push(formatPath(track));
    lines.push(formatTrackTag(track));
  }

  lines.push(`# total tracks: ${tracks.length}`);
  const minutes = (totalDuration(tracks) / 60).toFixed(2);
  lines.push(`# total duration: ${minutes} minutes`);
  return lines.join('\n');
}

