'use strict';

const UNIT_CODES = Object.freeze({ millimeters: 'G21', inches: 'G20' });

const fmt = (value) => Number(value).toFixed(3);

function unitsCommand(units) {
  const code = UNIT_CODES[units];
  if (!code) {
    throw new Error(`unsupported measurement units: ${units}`);
  }
  return `${code} ; measurements expressed in ${units}`;
}

function homeCommand(axes) {
  const letters = axes.map((axis) => String(axis).trim().toUpperCase()).join(' ');
  return `G28 ${letters}`;
}

function moveCommand(step, feedrate) {
  const position = `X${fmt(step.x)} Y${fmt(step.y)}`;
  return `G1 ${position} Z${fmt(step.z)} F${feedrate}`;
}

function extrudeCommand(step, feedrate) {
  return `G1 E${fmt(step.extrude)} F${feedrate}`;
}

function fanCommand(coolingPercent) {
  return `M106 S${Math.round((coolingPercent / 100) * 255)}`;
}

function slice(job) {
  const {
    material,
    units,
    bedTemperature,
    nozzleTemperature,
    speedMultiplier = 1,
    homing = ['X', 'Y', 'Z'],
    steps = [],
  } = job;

  const lines = [`; material: ${material}`];
  lines.push(`; print speed multiplier: ${speedMultiplier}`);
  lines.push(unitsCommand(units));
  lines.push(`M190 S${fmt(bedTemperature)}`);
  lines.push(`M109 S${fmt(nozzleTemperature)}`);
  lines.push(homeCommand(homing));

  for (const step of steps) {
    const feedrate = Math.round(step.speed * speedMultiplier);
    lines.push(moveCommand(step, feedrate));
    if (step.extrude) {
      lines.push(extrudeCommand(step, feedrate));
    }
    if (typeof step.cooling === 'number') {
      lines.push(fanCommand(step.cooling));
    }
  }

  lines.push(`; ${steps.length} movement steps processed`);
  return lines.join('\n');
}

console.log(slice({
