const LABEL_WIDTH = 10;

function label(name) {
  return `${name.padEnd(LABEL_WIDTH, ' ')}:`;
}

function row(name, value) {
  return label(name) + ` ${value}`;
}

function banner(username, hostname) {
  const title = username + `@${hostname}`;
  const rule = '-'.repeat(title.length);
  return `${title}\n` + rule;
}

function osLine(name, version) {
  return row('OS', name + ` ${version}`);
}

function plural(count, unit) {
  const suffix = count === 1 ? '' : 's';
  return `${count} ` + unit + suffix;
}

function uptimeLine(days, hours) {
  const dayPart = plural(days, 'day');
  return row('Uptime', dayPart + `, ${plural(hours, 'hour')}`);
}

function packagesLine(count, manager) {
  return row('Packages', count + ` (${manager})`);
}

function resolutionLine(width, height) {
  return row('Resolution', width + `x${height}`);
}

function memoryLine(used, total) {
  const percent = total > 0 ? Math.round((used / total) * 100) : 0;
  const ratio = `${used}MiB / ` + total + 'MiB';
  return row('Memory', ratio + ` (${percent}%)`);
}

function fetch(system) {
  return [
    banner(system.username, system.hostname),
    osLine(system.osName, system.osVersion),
    row('Kernel', system.kernelVersion),
    uptimeLine(system.uptimeDays, system.uptimeHours),
    packagesLine(system.packageCount, system.packageManager),
    row('Shell', system.shell),
    resolutionLine(system.displayWidth, system.displayHeight),
    row('DE', system.desktopEnvironment),
    memoryLine(system.memoryUsed, system.memoryTotal),
  ].join('\n');
}

