function validateContext(context) {
  const required = ['name', 'extension', 'callerIdName', 'greeting', 'tech', 'peer', 'timeout', 'voicemailBox'];
  const missing = required.filter((key) => context[key] === undefined || context[key] === '');
  if (missing.length > 0) {
    throw new Error(`Incomplete dialplan context, missing: ${missing.join(', ')}`);
  }
  if (!Number.isInteger(Number(context.timeout)) || Number(context.timeout) <= 0) {
    throw new Error(`Timeout must be a positive whole number of seconds, got ${context.timeout}`);
  }
  return context;
}

function step(extension, priority, application, argument) {
  const head = `exten => ${extension},${priority},${application}`;
  return argument === undefined ? head : `${head}(${argument})`;
}

function dialString(tech, peer, timeout) {
  return `${tech}/${peer},${timeout}`;
}

function dialplan(context) {
  const { name, extension, callerIdName, greeting, tech, peer, timeout, voicemailBox } = validateContext(context);
  const lines = [`[${name}]`];
  lines.push(step(extension, 1, 'Answer'));
  lines.push(step(extension, 2, 'Set', `CALLERID(name)=${callerIdName}`));
  lines.push(step(extension, 3, 'Playback', greeting));
  lines.push(step(extension, 4, 'Dial', dialString(tech, peer, timeout)));
  lines.push(step(extension, 5, 'NoOp', `WARNING: call to extension ${extension} was not completed`));
  lines.push(step(extension, 6, 'Voicemail', `${voicemailBox}@${name}`));
  lines.push(step(extension, 7, 'Hangup'));
  return lines.join('\n');
}

function describe(context) {
  const target = `${context.tech} peer ${context.peer}`;
  return `Context ${context.name}: extension ${context.extension} rings ${target} for ${context.timeout}s`;
}

function main() {
  const incoming = {
    name: 'incoming',
    extension: 100,
    callerIdName: 'Front Desk',
    greeting: 'welcome-greeting',
    tech: 'SIP',
    peer: 'reception',
    timeout: 20,
    voicemailBox: 100
  };

  console.log(describe(incoming));
  console.log(dialplan(incoming));

  const support = {
    ...incoming,
    name: 'support',
    extension: 200,
    callerIdName: 'Support Queue',
    peer: 'helpdesk',
    voicemailBox: 200
  };

  console.log(`\n${describe(support)}`);
  console.log(dialplan(support));
}

main();

