function formatOptions(parts) {
  return parts.join(',');
}

function swapEntry(device) {
  return `${device}\tnone\tswap\tsw\t0 0`;
}

function tmpEntry(size) {
  const options = formatOptions(['defaults', 'noatime', `size=${size}`]);
  return `tmpfs\t/tmp\ttmpfs\t${options}\t0 0`;
}

function nfsEntry(source, target, options) {
  return `${source}\t${target}\tnfs\t${options}\t0 0`;
}

function mounts(drives) {
  const {
    hostname,
    backupServer,
    backupPath,
    swapDevice,
    tmpSize,
    volumes = [],
  } = drives;

  if (!hostname) {
    throw new Error('a machine hostname is required to generate the mount table');
  }
  if (!backupServer) {
    throw new Error(`no backup server address supplied for ${hostname}`);
  }

  const lines = [`# /etc/fstab generated for ${hostname}`];

  lines.push(swapEntry(swapDevice));
  lines.push(tmpEntry(tmpSize));

  const backupSource = `${backupServer}:${backupPath}`;
  lines.push(nfsEntry(backupSource, '/mnt/backup', 'rw,hard,intr'));

  const publicSource = `${backupServer}:/export/public`;
  lines.push(nfsEntry(publicSource, '/mnt/public', 'ro,soft,intr'));

  volumes.forEach((volume) => {
    const { device, mountPoint } = volume;
    if (!device) {
      throw new Error(`volume mounted at ${mountPoint} has no device identifier`);
    }
    lines.push(`# physical volume for ${mountPoint}`);
    lines.push(`${device}\t${mountPoint}\text4\tdefaults\t0 2`);
  });

  lines.push(`# total physical volumes processed: ${volumes.length}`);

  return `${lines.join('\n')}\n`;
}

const config = mounts({
  hostname: 'server-one',
  backupServer: '10.0.0.12',
  backupPath: '/export/backups',
  swapDevice: '/dev/sdb',
  tmpSize: '4G',
  volumes: [
    { device: '/dev/sda1', mountPoint: '/' },
    { device: '/dev/sdc1', mountPoint: '/var/lib/data' },
    { device: 'UUID=9f2c-4a11', mountPoint: '/home' },
  ],
});

process.stdout.write(config);

module.exports = { mounts, swapEntry, tmpEntry, nfsEntry, formatOptions };

