function heading(text, level = 1) {
  return `h${level}. ${text}`;
}

function mention(username) {
  return `[~${username}]`;
}

function italic(text) {
  return `_${text}_`;
}

function panel(title, body) {
  const open = `{panel:title=${title}}`;
  return [open, body, '{panel}'].join('\n');
}

function codeBlock(language, body) {
  const open = `{code:${language}}`;
  return [open, body, '{code}'].join('\n');
}

function issueLink(ticket) {
  const target = `https://tracker.internal/browse/${ticket}`;
  return `[${ticket}|${target}]`;
}

function status(text, colour) {
  return `{status:colour=${colour}|title=${text}}`;
}

function wiki(document) {
  const {
    mainHeading,
    authorUsername,
    summary,
    warningTitle,
    warningMessage,
    codeLanguage,
    codeBody,
    issueTicket,
  } = document;

  const lines = [];
  lines.push(heading(mainHeading));
  lines.push(`Author: ${mention(authorUsername)}`);
  lines.push(italic(summary));
  lines.push(panel(warningTitle, warningMessage));
  lines.push(codeBlock(codeLanguage, codeBody));
  lines.push(`Tracking issue: ${issueLink(issueTicket)}`);
  lines.push(status('in progress', 'yellow'));
  lines.push(`Document generated for ${authorUsername}`);

  return lines.join('\n\n');
}

function main() {
  const document = {
    mainHeading: 'Project Status',
    authorUsername: 'jsmith',
    summary: 'A short overview of the current release readiness.',
    warningTitle: 'Deployment Freeze',
    warningMessage: 'Do not push to production until the freeze is lifted.',
    codeLanguage: 'javascript',
    codeBody: "console.log('deploy blocked');",
    issueTicket: 'BUG-123',
  };

  const rendered = wiki(document);
  console.log(rendered);
  console.log(`--- ${rendered.split('\n').length} lines of markup ---`);
}

main();

