function parseOctets(address, label) {
  const parts = String(address).split('.');
  if (parts.length !== 4) {
    throw new Error(`${label} must have four dot-separated octets, got "${address}"`);
  }
  return parts.map((part) => {
    const value = Number(part);
    if (!Number.isInteger(value) || value < 0 || value > 255) {
      throw new Error(`${label} contains an invalid octet: "${part}"`);
    }
    return value;
  });
}

function toNumber(address, label) {
  return parseOctets(address, label).reduce((acc, octet) => acc * 256 + octet, 0);
}

function validate(allocation) {
  const network = toNumber(allocation.network, 'network address');
  const mask = toNumber(allocation.netmask, 'subnet mask');
  if ((network & mask) !== network) {
    throw new Error(`network ${allocation.network} is not aligned to mask ${allocation.netmask}`);
  }
  const first = toNumber(allocation.rangeStart, 'pool start');
  const last = toNumber(allocation.rangeEnd, 'pool end');
  if (first > last) {
    throw new Error(`pool start ${allocation.rangeStart} is above pool end ${allocation.rangeEnd}`);
  }
  for (const [label, value] of [['pool start', first], ['pool end', last]]) {
    if ((value & mask) !== network) {
      throw new Error(`${label} falls outside the declared subnet`);
    }
  }
  const lease = Number(allocation.leaseTime);
  if (!Number.isInteger(lease) || lease <= 0) {
    throw new Error(`lease time must be a positive integer, got "${allocation.leaseTime}"`);
  }
  return lease;
}

function subnet(allocation) {
  const lease = validate(allocation);
  const lines = [];
  lines.push(`subnet ${allocation.network} netmask ${allocation.netmask} {`);
  lines.push(`  range ${allocation.rangeStart} ${allocation.rangeEnd};`);
  lines.push(`  option routers ${allocation.gateway};`);
  lines.push(`  option domain-name-servers ${allocation.dns};`);
  lines.push(`  option domain-name "${allocation.domainName}";`);
  lines.push(`  default-lease-time ${lease};`);
  lines.push(`  max-lease-time ${lease * 2};`);
  lines.push(`  # ${allocation.network} served through gateway ${allocation.gateway}`);
  lines.push('}');
  return lines.join('\n');
}

