function validate(application) {
  const required = ['type', 'name', 'comment', 'exec', 'icon'];
  for (const field of required) {
    if (!application[field]) {
      throw new Error(`Missing required desktop entry field: ${field}`);
    }
  }
  if (typeof application.startupNotify !== 'boolean') {
    throw new Error(`StartupNotify must be a boolean, got ${typeof application.startupNotify}`);
  }
  return application;
}

function execLine(exec, args) {
  const startup = (args || '').trim();
  return startup ? `${exec} ${startup}` : exec;
}

function categoriesLine(category) {
  const tag = category.trim();
  return tag.endsWith(';') ? tag : `${tag};`;
}

function keywordsLine(name, category) {
  const tag = category.replace(/;+$/, '');
  return `${name} ${tag}`;
}

function launcher(application) {
  const app = validate(application);
  const lines = ['[Desktop Entry]'];
  lines.push(`Type=${app.type}`);
  lines.push(`Name=${app.name}`);
  lines.push(`Comment=${app.comment}`);
  lines.push(`Exec=${execLine(app.exec, app.args)}`);
  lines.push(`Icon=${app.icon}`);
  lines.push(`StartupNotify=${app.startupNotify}`);
  lines.push(`Categories=${categoriesLine(app.category)}`);
  lines.push(`X-Keywords=${keywordsLine(app.name, app.category)}`);
  return `${lines.join('\n')}\n`;
}

function fileName(application) {
  const slug = application.name.trim().toLowerCase().replace(/\s+/g, '-');
  return `${slug}.desktop`;
}

function report(application) {
  const content = launcher(application);
  const header = `--- ${fileName(application)} (${content.split('\n').length - 1} lines) ---`;
  return `${header}\n${content}`;
}

const entries = [
  {
    type: 'Application',
    name: 'Text Editor',
    comment: 'Edit text files in the terminal',
    exec: '/usr/bin/nano',
    args: '%F',
    icon: 'accessories-text-editor',
    startupNotify: true,
    category: 'Utility'
  },
  {
    type: 'Application',
    name: 'System Monitor',
    comment: 'Watch running processes',
    exec: '/usr/bin/htop',
    args: '',
    icon: 'utilities-system-monitor',
    startupNotify: false,
    category: 'System;'
  }
];

for (const entry of entries) {
  process.stdout.write(report(entry));
}

module.exports = { launcher, fileName, report };

