function validateSetup(setup) {
  const required = ['modifier', 'terminal', 'menu', 'fontFamily', 'fontSize', 'output', 'resolution', 'wallpaper'];
  const missing = required.filter((key) => setup[key] === undefined || setup[key] === '');
  if (missing.length > 0) {
    throw new Error(`Incomplete window manager setup: missing ${missing.join(', ')}`);
  }
  const size = Number(setup.fontSize);
  if (!Number.isFinite(size) || size <= 0) {
    throw new Error(`Font size must be a positive number, received ${setup.fontSize}`);
  }
  return { ...setup, fontSize: size };
}

function setVariable(name, value) {
  return `set $${name} ${value}`;
}

function fontLine(family, size) {
  return `font pango:${family} ${size}`;
}

function bindKey(combo, command) {
  return `bindsym ${combo} exec ${command}`;
}

function outputMode(output, resolution) {
  return `output ${output} mode ${resolution}`;
}

function outputBackground(output, wallpaper) {
  return `output ${output} bg ${wallpaper} stretch`;
}

function window(setup) {
  const cfg = validateSetup(setup);
  const lines = [
    setVariable('mod', cfg.modifier),
    setVariable('term', cfg.terminal),
    setVariable('menu', cfg.menu),
    fontLine(cfg.fontFamily, cfg.fontSize),
    bindKey('$mod+Return', '$term'),
    bindKey('$mod+d', '$menu'),
    outputMode(cfg.output, cfg.resolution),
    outputBackground(cfg.output, cfg.wallpaper),
  ];
  return `${lines.join('\n')}\n`;
}

function describe(setup) {
  const parts = [
    `modifier ${setup.modifier}`,
    `terminal ${setup.terminal}`,
    `launcher ${setup.menu}`,
    `display ${setup.output} at ${setup.resolution}`,
  ];
  return `Generating config for ${parts.join(', ')}`;
}

const desktop = {
  modifier: 'Mod4',
  terminal: 'alacritty',
  menu: 'dmenu_run',
  fontFamily: 'DejaVu Sans Mono',
  fontSize: 12,
  output: 'HDMI-A-1',
  resolution: '1920x1080@60Hz',
  wallpaper: '/usr/share/backgrounds/nebula.png',
};

console.log(describe(desktop));
console.log(window(desktop));

