function passengerSection(flight) {
  const fullName = `${flight.firstName} ${flight.lastName}`;
  return [
    `Passenger: ${fullName}`,
    `Frequent Flyer #: ${flight.frequentFlyer || 'none'}`,
  ];
}

function flightSection(flight) {
  const departure = formatDate(flight.departureDate);
  return [
    `Airline: ${flight.airline}`,
    `Flight: ${flight.flightNumber}`,
    `Departure Date: ${departure}`,
  ];
}

function boardingSection(flight) {
  return [
    `Gate: ${flight.gate}`,
    `Seat: ${flight.seat}`,
    `Boarding Time: ${formatTime(flight.boardingTime)}`,
  ];
}

function routingSection(flight) {
  const route = `${flight.origin} -> ${flight.destination}`;
  return [
    `Route: ${route}`,
    `Duration: ${formatDuration(flight.durationMinutes)}`,
  ];
}

function formatDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`Invalid departure date: ${value}`);
  }
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

function formatTime(value) {
  const [hours, minutes] = String(value).split(':');
  const hour = Number(hours);
  const suffix = hour < 12 ? 'AM' : 'PM';
  const display = hour % 12 === 0 ? 12 : hour % 12;
  return `${display}:${minutes} ${suffix}`;
}

function formatDuration(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return `${hours}h ${rest}m`;
}

function ticket(flight) {
  const lines = [
    ...passengerSection(flight),
    ...flightSection(flight),
    ...boardingSection(flight),
    ...routingSection(flight),
  ];
  return lines.join('\n');
}

