const WIDTH = 40;

function money(amount) {
  return `$${amount.toFixed(2)}`;
}

function percent(rate, decimals) {
  return `${(rate * 100).toFixed(decimals)}%`;
}

function padColumns(label, value) {
  const gap = Math.max(1, WIDTH - label.length - value.length);
  return label + ' '.repeat(gap) + value;
}

function formatHeader(restaurant) {
  const name = restaurant.name.toUpperCase();
  const address = [restaurant.street, restaurant.city].join(', ');
  const phone = `Tel: ${restaurant.phone}`;
  return [name, address, phone];
}

function formatDate(value) {
  const d = value instanceof Date ? value : new Date(value);
  const day = `${d.getDate()}`.padStart(2, '0');
  const month = `${d.getMonth() + 1}`.padStart(2, '0');
  return [day, month, d.getFullYear()].join('/');
}

function formatOrderDetails(order) {
  const server = `Server: ${order.server}`;
  const table = `Table: ${order.table}`;
  const date = `Date: ${formatDate(order.date)}`;
  return [server, table, date];
}

function formatItemLine(item) {
  const label = [item.quantity, 'x', item.name].join(' ');
  return padColumns(label, money(item.quantity * item.price));
}

function formatTotals(subtotal, taxRate, tipRate) {
  const tax = subtotal * taxRate;
  const tip = subtotal * tipRate;
  const subtotalLine = padColumns('Subtotal', money(subtotal));
  const taxLabel = `Tax (${percent(taxRate, 1)})`;
  const tipLabel = `Suggested tip (${percent(tipRate, 0)})`;
  return [
    subtotalLine,
    padColumns(taxLabel, money(tax)),
    padColumns(tipLabel, money(tip)),
    padColumns('TOTAL', money(subtotal + tax)),
  ];
}

function receipt(order) {
  if (!order || !Array.isArray(order.items) || order.items.length === 0) {
    throw new Error(`Cannot print a receipt without items for table ${order && order.table}`);
  }
  const subtotal = order.items.reduce((sum, item) => sum + item.quantity * item.price, 0);
  const rule = '-'.repeat(WIDTH);
  const lines = [
    ...formatHeader(order.restaurant),
    rule,
    ...formatOrderDetails(order),
    rule,
    ...order.items.map(formatItemLine),
    rule,
    ...formatTotals(subtotal, order.taxRate, order.tipRate),
    '',
    `Thank you for dining with us, ${order.guestName}!`,
  ];
  return lines.join('\n');
}

