function formatHeader(version) {
  const titleLine = `Release ${version.number}`;
  const dateLine = `Date: ${version.date}`;
  const authorLine = `Primary author: ${version.author}`;
  return [titleLine, dateLine, authorLine];
}

function formatBreakingChange(change) {
  const subject = `${change.component}: ${change.description}`;
  return `- ${subject} Migration: ${change.migration}`;
}

function formatFeature(feature) {
  const headline = `${feature.module} now ${feature.description}`;
  return `- ${headline} (issue #${feature.issue})`;
}

function formatFix(fix) {
  const outcome = `${fix.description} — ${fix.resolution}`;
  return `- ${outcome} Reported by ${fix.reporter}.`;
}

function section(title, entries, emptyNote) {
  if (entries.length === 0) {
    const note = `  ${emptyNote}`;
    return [title, note];
  }
  const heading = `${title} (${entries.length})`;
  return [heading, ...entries];
}

function release(version) {
  if (!version || !version.number) {
    throw new Error('Invalid release data: missing version number');
  }
  const lines = formatHeader(version);
  const breaking = (version.breakingChanges || []).map(formatBreakingChange);
  const features = (version.features || []).map(formatFeature);
  const fixes = (version.fixes || []).map(formatFix);
  lines.push('');
  lines.push(...section('Breaking changes', breaking, 'None in this release.'));
  lines.push('');
  lines.push(...section('New features', features, 'None in this release.'));
  lines.push('');
  lines.push(...section('Bug fixes', fixes, 'None in this release.'));
  lines.push('');
  const total = breaking.length + features.length + fixes.length;
  lines.push(`Total documented entries: ${total}`);
  return lines.join('\n');
}

const upcoming = {
  number: '3.2.0',
  date: 'Monday, 4 March 2024',
  author: 'Alice',
  breakingChanges: [
    {
      component: 'config loader',
      description: 'YAML files are no longer read from the home directory.',
      migration: 'move config.yaml into ./etc and run `app config migrate`.',
    },
  ],
  features: [
    { module: 'scheduler', description: 'supports cron expressions with seconds', issue: 812 },
    { module: 'http client', description: 'retries idempotent requests automatically', issue: 845 },
    { module: 'cli', description: 'prints machine-readable JSON with --format json', issue: 851 },
  ],
  fixes: [
    { description: 'Crash when parsing empty payloads', resolution: 'guard added in the decoder', reporter: 'Bob' },
    { description: 'Timestamps drifted under heavy load', resolution: 'switched to a monotonic clock', reporter: 'Carol' },
    { description: 'Log rotation skipped the first file', resolution: 'index now starts at zero', reporter: 'Dave' },
  ],
};

console.log(release(upcoming));

module.exports = { release, formatHeader, formatBreakingChange, formatFeature, formatFix };

