function formatOverview(round) {
  const roundSentence = `Round ${round.number} is now complete.`;
  const phaseSentence = `The current phase is ${round.phase}.`;
  const activeSentence = `The active player is ${round.activePlayer}.`;
  return [roundSentence, phaseSentence, activeSentence];
}

function formatAction(action) {
  return `${action.player} performed ${action.type} against ${action.target}.`;
}

function formatActions(actions) {
  if (actions.length === 0) {
    return ['No actions were taken this round.'];
  }
  return actions.map(formatAction);
}

function formatDelta(amount) {
  if (amount > 0) {
    return `gained ${amount}`;
  }
  if (amount < 0) {
    return `lost ${Math.abs(amount)}`;
  }
  return 'held steady with';
}

function formatResources(resources) {
  const woodLine = `The players ${formatDelta(resources.wood)} wood.`;
  const clayLine = `The players ${formatDelta(resources.clay)} clay.`;
  const wheatLine = `The players ${formatDelta(resources.wheat)} wheat.`;
  return [woodLine, clayLine, wheatLine];
}

function formatStandings(standings) {
  const ranked = [...standings].sort((a, b) => b.score - a.score);
  const [first, second] = ranked;
  const leadSentence = `${first.name} leads with ${first.score} points.`;
  const runnerSentence = `${second.name} follows with ${second.score} points.`;
  return [leadSentence, runnerSentence];
}

function summarize(round) {
  const sentences = [
    ...formatOverview(round),
    ...formatActions(round.actions),
    ...formatResources(round.resources),
    ...formatStandings(round.standings),
  ];
  return sentences.join(' ');
}

function main() {
  const round = {
    number: 3,
    phase: 'building',
    activePlayer: 'Mira',
    actions: [
      { player: 'Mira', type: 'a trade offer', target: 'Tobias' },
      { player: 'Tobias', type: 'a blockade', target: 'the north road' },
    ],
    resources: { wood: 4, clay: -2, wheat: 0 },
    standings: [
      { name: 'Tobias', score: 17 },
      { name: 'Mira', score: 21 },
    ],
  };

  console.log(summarize(round));
  console.log(`Summary length: ${summarize(round).length} characters.`);
}

main();

module.exports = { summarize, formatOverview, formatActions, formatResources, formatStandings };

