  const signSentence = `Your zodiac sign is ${reading.sign}.`;
  const elementSentence = `Its elemental group is ${reading.element}.`;
  const rulerSentence = `It is ruled by the planet ${reading.rulingPlanet}.`;
  return [signSentence, elementSentence, rulerSentence];
}

function dateInfo(reading) {
  const today = formatDate(reading.date);
  const dateSentence = `Today is ${today}.`;
  const timeSentence = `Your luckiest hours fall around ${reading.luckyTime}.`;
  return [dateSentence, timeSentence];
}

function predictionSentence(category, prediction) {
  const intensity = `a ${prediction.intensity} intensity`;
  return `In matters of ${category}, ${prediction.text}, carried by ${intensity}.`;
}

function corePredictions(reading) {
  return Object.keys(reading.predictions).map((category) =>
    predictionSentence(category, reading.predictions[category]));
}

