function lastFour(accountNumber) {
  const digits = String(accountNumber).replace(/\D/g, '');
  if (digits.length < 4) {
    throw new Error('Account number "' + accountNumber + '" has fewer than four digits');
  }
  return digits.slice(-4);
}

function money(amount, currency) {
  const value = Number(amount);
  if (!Number.isFinite(value)) {
    throw new Error('Amount "' + amount + '" is not a number');
  }
  return currency + ' ' + value.toFixed(2);
}

function monthLabel(month) {
  const parsed = new Date(month + '-01T00:00:00');
  if (Number.isNaN(parsed.getTime())) {
    return String(month);
  }
  const names = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];
  return names[parsed.getMonth()] + ' ' + parsed.getFullYear();
}

function formatAccountId(statement) {
  const bank = 'Bank: ' + statement.bankName;
  const card = 'Account ending ' + lastFour(statement.accountNumber);
  const period = 'Statement month: ' + monthLabel(statement.month);
  return [bank, card, period];
}

function formatBalances(statement) {
  const { currency } = statement;
  const opening = 'Opening balance: ' + money(statement.openingBalance, currency);
  const closing = 'Closing balance: ' + money(statement.closingBalance, currency);
  const unit = 'All figures in ' + currency;
  return [opening, closing, unit];
}

function formatTopExpense(statement) {
  const expense = statement.topExpense;
  const merchant = 'Largest payment went to ' + expense.merchant + '.';
  const spent = money(expense.amount, statement.currency);
  const detail = 'You paid ' + spent + ' on ' + expense.date + '.';
  return [merchant, detail];
}

function formatBudgetAlert(statement) {
  const budget = statement.budget;
  const kind = 'Budget type: ' + budget.limitType;
  const limit = money(budget.threshold, statement.currency);
  const warning = 'Warning threshold: ' + limit;
  const spent = money(budget.spent, statement.currency);
  const current = 'Spent so far: ' + spent;
  return [kind, warning, current];
}

function sms(statement) {
