function parseDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Unreadable dive date: ${value}`);
  }
  return date;
}

function formatDate(value) {
  const date = parseDate(value);
  const day = `${date.getDate()}`.padStart(2, '0');
  const month = `${date.getMonth() + 1}`.padStart(2, '0');
  return `${day}/${month}/${date.getFullYear()}`;
}

function depth(metres) {
  return `${metres.toFixed(1)} m`;
}

function pressure(bar) {
  return `${Math.round(bar)} bar`;
}

function duration(minutes) {
  const hours = Math.floor(minutes / 60);
  if (hours === 0) {
    return `${minutes} min`;
  }
  const rest = `${minutes % 60}`.padStart(2, '0');
  return `${hours} h ${rest} min`;
}

function validate(dive) {
  const required = ['location', 'site', 'date', 'maxDepth', 'averageDepth',
    'bottomTime', 'startPressure', 'endPressure'];
  for (const key of required) {
    if (dive[key] === undefined || dive[key] === null) {
      throw new TypeError(`Dive log is missing the field "${key}"`);
    }
  }
  if (dive.averageDepth > dive.maxDepth) {
    throw new RangeError(`Average depth ${dive.averageDepth} exceeds max depth ${dive.maxDepth}`);
  }
  if (dive.endPressure > dive.startPressure) {
    throw new RangeError(`End pressure cannot be above the start pressure of ${dive.startPressure} bar`);
  }
}

function format(dive) {
  validate(dive);
  const gasUsed = dive.startPressure - dive.endPressure;
  return [
    `${dive.location} — ${dive.site}`,
    `Date: ${formatDate(dive.date)}`,
    `Max depth: ${depth(dive.maxDepth)}`,
    `Average depth: ${depth(dive.averageDepth)}`,
    `Bottom time: ${duration(dive.bottomTime)}`,
    `Start pressure: ${pressure(dive.startPressure)}`,
    `End pressure: ${pressure(dive.endPressure)}`,
    `Gas used: ${pressure(gasUsed)}`,
  ];
}

const lastDive = {
  location: 'Dahab, Egypt',
  site: 'The Blue Hole',
  date: '2024-04-17',
  maxDepth: 29.4,
  averageDepth: 16.8,
  bottomTime: 47,
  startPressure: 210,
  endPressure: 60,
};

console.log(format(lastDive).join('\n'));

module.exports = { format, formatDate, duration };

