  if (Number.isNaN(date.getTime())) {
    throw new TypeError(`Encounter date "${dateInput}" is not a valid date`);
  }
  const month = `${date.getMonth() + 1}`.padStart(2, '0');
  const day = `${date.getDate()}`.padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
}

function formatMonster(monster) {
  const initiative = Number(monster.initiative);
  const rolled = Number.isFinite(initiative) ? initiative : 0;
  return `  ${monster.name} rolled initiative ${rolled}`;
}

function summarize(encounter) {
  const {
    campaignName,
    environmentType,
    partyLevel,
    difficultyRating,
