function normalizeCallsign(callsign) {
  const trimmed = String(callsign).trim().toUpperCase();
  if (!/^[A-Z0-9/]{3,}$/.test(trimmed)) {
    throw new Error(`Invalid callsign: ${trimmed}`);
  }
  return trimmed;
}

function formatFrequency(frequency) {
  const megahertz = Number(frequency);
  if (!Number.isFinite(megahertz) || megahertz <= 0) {
    throw new Error(`Invalid frequency: ${frequency}`);
  }
  return `${megahertz.toFixed(3)} MHz`;
}

function formatReport(report) {
  const digits = String(report).trim();
  if (!/^\d{2,3}$/.test(digits)) {
    throw new Error(`Invalid signal report: ${digits}`);
  }
  return digits;
}

function verificationCode(callsign, frequency) {
  const kilohertz = Math.round(Number(frequency) * 1000);
  const letters = callsign.replace(/[^A-Z0-9]/g, '');
  const checksum = (kilohertz % 97).toString().padStart(2, '0');
  return `${letters}-${kilohertz}-${checksum}`;
}

function export_(contact) {
  const callsign = normalizeCallsign(contact.callsign);
  const operator = String(contact.operatorName).trim();
  const records = [];
  records.push(`Callsign ${callsign} operated by ${operator}`);
  records.push(`Station location: ${String(contact.stationLocation).trim()}`);
  records.push(`Band: ${String(contact.band).trim()}`);
  records.push(`Frequency: ${formatFrequency(contact.frequency)}`);
  records.push(`Mode: ${String(contact.mode).trim().toUpperCase()}`);
  records.push(`Signal sent: ${formatReport(contact.signalSent)}`);
  records.push(`Signal received: ${formatReport(contact.signalReceived)}`);
  records.push(`Verification: ${verificationCode(callsign, contact.frequency)}`);
  return records;
}

export { export_ as export };

