const REQUIRED_FIELDS = [
  'offeringTeam',
  'receivingTeam',
  'league',
  'week',
  'offeredPlayer',
  'requestedPlayer',
  'deadlineDay',
  'commissioner',
];

function validate(trade) {
  if (!trade || typeof trade !== 'object') {
    throw new TypeError('propose() expects a trade object');
  }
  const missing = REQUIRED_FIELDS.filter((field) => {
    const value = trade[field];
    return value === undefined || value === null || `${value}`.trim() === '';
  });
  if (missing.length > 0) {
    throw new Error(`Incomplete trade proposal, missing: ${missing.join(', ')}`);
  }
  const week = Number(trade.week);
  if (!Number.isInteger(week) || week < 1 || week > 18) {
    throw new RangeError(`Week ${trade.week} is outside the fantasy season (1-18)`);
  }
  return week;
}

function propose(trade) {
  const week = validate(trade);
  const from = `${trade.offeringTeam}`.trim();
  const to = `${trade.receivingTeam}`.trim();
  return [
    `Hello ${to}, this is ${from} reaching out about a trade.`,
    `We are both competing in the ${trade.league} this season.`,
    `This proposal is aimed at your Week ${week} lineup.`,
    `I am willing to send you ${trade.offeredPlayer} right away.`,
    `In return I would need ${trade.requestedPlayer} on my roster.`,
    `Please give me your answer by ${trade.deadlineDay} at the latest.`,
    `Commissioner ${trade.commissioner} is copied on this message for approval.`,
    `Thanks for considering it, ${from}.`,
  ];
}

function formatProposal(trade) {
  const sentences = propose(trade);
  const body = sentences.map((sentence, index) => `${index + 1}. ${sentence}`).join('\n');
  const header = `TRADE PROPOSAL: ${trade.offeringTeam} -> ${trade.receivingTeam}`;
  return `${header}\n${body}`;
}

function main() {
  const trade = {
    offeringTeam: 'Gridiron Ghosts',
    receivingTeam: 'Bayou Bengals',
    league: 'Sunday Funday League',
    week: 7,
    offeredPlayer: 'Tyreek Hill',
    requestedPlayer: 'Bijan Robinson',
    deadlineDay: 'Friday',
    commissioner: 'Dana Whitmore',
  };
  console.log(formatProposal(trade));

  try {
    propose({ ...trade, week: 24 });
  } catch (err) {
    console.error(`Rejected proposal: ${err.message}`);
  }
}

main();

module.exports = { propose, formatProposal };

