const REQUIRED_FIELDS = [
  'title',
  'author',
  'email',
  'license',
  'created',
  'welcome',
  'linkUrl',
  'linkDescription',
];

function validate(page) {
  const missing = REQUIRED_FIELDS.filter((field) => {
    const value = page[field];
    return value === undefined || value === null || String(value).trim() === '';
  });
  if (missing.length > 0) {
    throw new Error(`Incomplete page data, missing: ${missing.join(', ')}`);
  }
  if (!String(page.email).includes('@')) {
    throw new Error(`Invalid contact email: ${page.email}`);
  }
}

function formatDate(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    return String(value).trim();
  }
  const month = String(date.getUTCMonth() + 1).padStart(2, '0');
  const day = String(date.getUTCDate()).padStart(2, '0');
  return `${date.getUTCFullYear()}-${month}-${day}`;
}

function format(page) {
  validate(page);
  const created = formatDate(page.created);
  const lines = [];
  lines.push(`# ${String(page.title).trim()}`);
  lines.push(`Author: ${String(page.author).trim()}`);
  lines.push(`Contact: ${String(page.email).trim()}`);
  lines.push(`License: ${String(page.license).trim()}`);
  lines.push(`Created: ${created}`);
  lines.push(`> ${String(page.welcome).trim()}`);
  const url = String(page.linkUrl).trim();
  lines.push(`=> ${url} ${String(page.linkDescription).trim()}`);
  lines.push(`--- ${page.author} | ${created} ---`);
  return lines;
}

function render(page) {
  return `${format(page).join('\n')}\n`;
}

function main() {
  const page = {
    title: 'Capsule of Small Things',
    author: 'Ada Rivera',
    email: 'ada@example.org',
    license: 'CC BY-SA 4.0',
    created: '2024-03-07',
    welcome: 'Welcome aboard, traveller of the small web.',
    linkUrl: 'gemini://example.org/log/',
    linkDescription: 'Daily log entries',
  };
  process.stdout.write(render(page));
  try {
    format({ ...page, email: 'ada.example.org' });
  } catch (error) {
    process.stderr.write(`Could not format page: ${error.message}\n`);
  }
}

main();

module.exports = { format, render, formatDate };

