function formatDuration(seconds) {
  const minutes = Math.floor(seconds / 60);
  const rest = String(seconds % 60).padStart(2, '0');
  return `${minutes}:${rest}`;
}

function formatWeapon(weapon) {
  const normalized = weapon.trim().toLowerCase();
  const known = ['foil', 'epee', 'sabre'];
  if (!known.includes(normalized)) {
    throw new Error(`Unknown weapon: ${weapon}`);
  }
  return normalized.charAt(0).toUpperCase() + normalized.slice(1);
}

function summarize(bout) {
  const {
    redFencer,
    blueFencer,
    weapon,
    pool,
    referee,
    timeLimit,
    redScore,
    blueScore,
  } = bout;

  const lines = [];
  lines.push(`${redFencer} vs ${blueFencer}`);
  lines.push(`Weapon: ${formatWeapon(weapon)}`);
  lines.push(`Pool: ${pool}`);
  lines.push(`Referee: ${referee}`);
  lines.push(`Time limit: ${formatDuration(timeLimit)}`);
  lines.push(`Red score: ${redScore}`);
  lines.push(`Blue score: ${blueScore}`);
  lines.push(`Point difference: ${redScore - blueScore}`);
  return lines;
}

function describeOutcome(bout) {
  const margin = bout.redScore - bout.blueScore;
  if (margin === 0) {
    return `${bout.redFencer} and ${bout.blueFencer} finished level`;
  }
  const winner = margin > 0 ? bout.redFencer : bout.blueFencer;
  return `${winner} wins by ${Math.abs(margin)} touch(es)`;
}

function report(bouts) {
  return bouts
    .map((bout, index) => {
      const header = `Bout ${index + 1}`;
      const body = summarize(bout).join('\n');
      const verdict = describeOutcome(bout);
      return `${header}\n${body}\n${verdict}`;
    })
    .join('\n\n');
}

const schedule = [
  {
    redFencer: 'Marchetti',
    blueFencer: 'Okonkwo',
    weapon: 'foil',
    pool: 3,
    referee: 'L. Duval',
    timeLimit: 180,
    redScore: 5,
    blueScore: 3,
  },
  {
    redFencer: 'Ivanova',
    blueFencer: 'Tanaka',
    weapon: 'sabre',
    pool: 7,
    referee: 'R. Hassan',
    timeLimit: 480,
    redScore: 12,
    blueScore: 15,
  },
];

console.log(report(schedule));

module.exports = { summarize, describeOutcome, report, formatDuration, formatWeapon };

