function describeRow(row) {
  const label = `Row ${row.rowNumber}`;
  const lowLabel = label.toLowerCase();
  const stitchPhrase = `${row.stitchType} stitches.`;
  const lines = [];
  lines.push(label + `: use ${row.yarnColor} yarn.`);
  lines.push(`  Work ${row.stitchCount} ` + stitchPhrase);
  lines.push(`  Recommended needle size for this section: ${row.needleSize}.`);
  lines.push(`  Keep a ${row.tensionLevel} tension throughout ` + lowLabel + '.');
  if (row.stitchCount > 50) {
    lines.push(`  Tip: place a stitch marker after 25 stitches on ${lowLabel}.`);
  }
  return lines;
}

function normalizeRow(item, index) {
  const position = `Row at position ${index + 1}`;
  const missing = ['stitchType', 'stitchCount', 'yarnColor', 'needleSize', 'tensionLevel']
    .filter((key) => item[key] === undefined || item[key] === null);
  if (missing.length > 0) {
    throw new Error(position + ` is missing: ${missing.join(', ')}`);
  }
  const stitchCount = Number(item.stitchCount);
  if (!Number.isFinite(stitchCount) || stitchCount <= 0) {
    throw new Error(position + ` has an invalid stitch count: ${item.stitchCount}`);
  }
  return {
    rowNumber: item.rowNumber === undefined ? index + 1 : item.rowNumber,
    stitchType: item.stitchType,
    stitchCount,
    yarnColor: item.yarnColor,
    needleSize: item.needleSize,
    tensionLevel: item.tensionLevel,
  };
}

function generate(rows) {
  if (!Array.isArray(rows)) {
    throw new TypeError(`generate expects a list of rows, received ${typeof rows}`);
  }
  const pattern = rows.map(normalizeRow);
  const totalRows = pattern.length;
  const guide = ['Starting a new knitting project!'];
  guide.push(`This pattern has ${totalRows} rows in total.`);
  pattern.forEach((row) => {
    describeRow(row).forEach((line) => guide.push(line));
  });
  guide.push('Your project is ready for blocking.');
  guide.push(`Congratulations on finishing all ${totalRows} rows of your project!`);
  return guide.join('\n');
}

function summarizeYarn(rows) {
  const totals = new Map();
  rows.forEach((row) => {
    const previous = totals.get(row.yarnColor) || 0;
    totals.set(row.yarnColor, previous + Number(row.stitchCount));
  });
  return [...totals.entries()]
    .map(([color, stitches]) => color + `: ${stitches} stitches`)
    .join(' | ');
}

function main() {
  const rows = [
    { rowNumber: 1, stitchType: 'purl', stitchCount: 60, yarnColor: 'red', needleSize: 5, tensionLevel: 'tight' },
    { rowNumber: 2, stitchType: 'knit', stitchCount: 40, yarnColor: 'cream', needleSize: 5, tensionLevel: 'even' },
    { rowNumber: 3, stitchType: 'rib', stitchCount: 52, yarnColor: 'red', needleSize: 4, tensionLevel: 'loose' },
  ];
  console.log(generate(rows));
  console.log(`Yarn shopping list -> ${summarizeYarn(rows)}`);
}

main();

module.exports = { generate, describeRow, summarizeYarn };

