function formatAgeInMonths(ageInMonths) {
  const unit = ageInMonths === 1 ? 'month' : 'months';
  return `${ageInMonths} ${unit} old`;
}

function formatWeight(weightInPounds) {
  const rounded = Math.round(weightInPounds * 10) / 10;
  return `${rounded} lbs`;
}

function normalizeAnimal(animal, index) {
  const name = String(animal.name || '').trim();
  if (!name) {
    throw new Error(`Animal at position ${index + 1} is missing a name.`);
  }
  const age = Number(animal.ageInMonths);
  if (!Number.isFinite(age) || age < 0) {
    throw new Error(`${name} has an invalid age in months.`);
  }
  const weight = Number(animal.weightInPounds);
  if (!Number.isFinite(weight) || weight <= 0) {
