const HEADER = 'DESERT METEORITE RECOVERY EXPEDITION - FIELD REPORT';

function formatCoordinate(value, positiveSuffix, negativeSuffix) {
  const hemisphere = value >= 0 ? positiveSuffix : negativeSuffix;
  return `${Math.abs(value).toFixed(4)}\u00B0 ${hemisphere}`;
}

function formatLocation(latitude, longitude) {
  const lat = formatCoordinate(latitude, 'N', 'S');
  const lon = formatCoordinate(longitude, 'E', 'W');
  return `${lat}, ${lon}`;
}

function formatMass(massGrams) {
  if (massGrams >= 1000) {
    const kilograms = (massGrams / 1000).toFixed(3);
    return `${massGrams} g (${kilograms} kg)`;
  }
  return `${massGrams} g`;
}

function describeFind(find) {
  const lines = [];
  lines.push(`Specimen ${find.specimenNumber} - classification: ${find.structuralClassification}`);
  lines.push(`  Mass: ${formatMass(find.massGrams)}`);
  lines.push(`  Recovered at ${formatLocation(find.latitude, find.longitude)}`);
  lines.push(`  Weathering grade observed on crust: ${find.weatheringGrade}`);
  if (find.massGrams > 1000) {
    lines.push(`  *** MAJOR DISCOVERY: specimen ${find.specimenNumber} exceeds 1000 g ***`);
  }
  return lines;
}

function catalog(finds) {
  if (!Array.isArray(finds)) {
    throw new TypeError(`catalog expects an array of finds, received ${typeof finds}`);
  }
  const report = [HEADER, '='.repeat(HEADER.length)];
  report.push(`Total specimens recovered: ${finds.length}`);
  report.push('');
  finds.forEach((find, index) => {
    report.push(`Find #${index + 1}`);
    describeFind(find).forEach((line) => report.push(line));
    report.push('');
  });
  report.push(`--- END OF DAILY LOG: ${finds.length} specimens secured ---`);
  report.push('All samples are sealed for transport.');
  return report.join('\n');
}

function main() {
  const finds = [
    {
      specimenNumber: 'ROCK-001',
      massGrams: 500,
      structuralClassification: 'chondrite',
      latitude: 45,
      longitude: 90,
      weatheringGrade: 'moderate',
    },
    {
      specimenNumber: 'ROCK-002',
      massGrams: 2450,
      structuralClassification: 'iron octahedrite',
      latitude: -23.5,
      longitude: -15.25,
      weatheringGrade: 'severe',
    },
  ];
  console.log(catalog(finds));
}

main();

module.exports = { catalog, describeFind, formatLocation, formatMass };

