function formatSeconds(seconds) {
  const unit = Math.abs(seconds) === 1 ? 'second' : 'seconds';
  return `${seconds} ${unit}`;
}

function validateCue(cue, index) {
  const position = index + 1;
  if (typeof cue !== 'object' || cue === null) {
    throw new TypeError(`Cue at position ${position} must be an object.`);
  }
  const { number, scene, fade, focus, gel, intensity } = cue;
  if (!Number.isInteger(number) || number < 1) {
    throw new RangeError(`Cue at position ${position} needs a positive integer cue number.`);
  }
  if (typeof scene !== 'string' || scene.trim() === '') {
    throw new TypeError(`Cue ${number} is missing a scene name.`);
  }
  if (typeof fade !== 'number' || Number.isNaN(fade) || fade < 0) {
    throw new RangeError(`Cue ${number} needs a fade time of zero or more seconds.`);
  }
  if (typeof focus !== 'string' || focus.trim() === '') {
    throw new TypeError(`Cue ${number} is missing a stage focus area.`);
  }
  if (typeof gel !== 'string' || gel.trim() === '') {
    throw new TypeError(`Cue ${number} is missing a color gel name.`);
  }
  if (typeof intensity !== 'number' || intensity < 0 || intensity > 100) {
    throw new RangeError(`Cue ${number} has an intensity outside 0-100: ${intensity}.`);
  }
  return { number, scene: scene.trim(), fade, focus: focus.trim(), gel: gel.trim(), intensity };
}

function cueLines(cue) {
  const lines = [];
  lines.push(`CUE ${cue.number} — "${cue.scene}"`);
  lines.push(`  Fade transition over ${formatSeconds(cue.fade)}.`);
  lines.push(`  Direct the spotlight to ${cue.focus}.`);
  lines.push(`  Insert the ${cue.gel} gel.`);
  lines.push(`  Set the lamp to ${cue.intensity}% intensity.`);
  if (cue.intensity === 100) {
    lines.push(`  WARNING: extreme heat at ${cue.focus} — do not touch the fixture.`);
  }
  return lines;
}

function build(cues) {
  if (!Array.isArray(cues)) {
    throw new TypeError(`build expects a list of cues, received ${typeof cues}.`);
  }
  const checked = cues.map(validateCue);
  const total = checked.length;
  const label = total === 1 ? 'lighting cue' : 'lighting cues';
  const sheet = ['LIGHTING BOOTH OPERATOR GUIDE'];
  sheet.push(`This act contains ${total} ${label}.`);
  for (const cue of checked) {
    sheet.push(...cueLines(cue));
  }
  sheet.push(`END OF ACT after all ${total} ${label}.`);
  sheet.push('Crew: reset all fixtures and gels for intermission.');
  return sheet.join('\n');
}

const actOne = [
  { number: 1, scene: 'opening number', fade: 5, focus: 'center stage', gel: 'warm amber', intensity: 80 },
  { number: 2, scene: 'the confession', fade: 3, focus: 'stage left apron', gel: 'steel blue', intensity: 100 },
  { number: 3, scene: 'curtain call', fade: 1, focus: 'full stage wash', gel: 'no color', intensity: 95 },
];

console.log(build(actOne));
console.log(`\nSheet generated for ${actOne.length} cues.`);

module.exports = { build, cueLines, formatSeconds };

