const FORMAT_LABELS = {
  standard: 'Standard',
  'iron person': 'Iron Person',
  bp: 'British Parliamentary',
  ap: 'Asian Parliamentary'
};

function describeFormat(format) {
  const key = String(format).trim().toLowerCase();
  return FORMAT_LABELS[key] || `${String(format).trim()}`;
}

function isIronPerson(format) {
  return String(format).trim().toLowerCase() === 'iron person';
}

function validateDebate(debate, index) {
  const required = ['room', 'motion', 'proposition', 'opposition', 'adjudicator', 'format'];
  for (const field of required) {
    if (debate[field] === undefined || debate[field] === null || `${debate[field]}`.trim() === '') {
      throw new Error(`Debate ${index + 1} is missing the "${field}" field.`);
    }
  }
}

function describeMatch(debate, index) {
  validateDebate(debate, index);
  const lines = [];
  lines.push(`Match ${index + 1}: please proceed to Room ${debate.room}.`);
  lines.push(`The motion for debate is: "${debate.motion}".`);
  lines.push(`Speaking for the proposition: ${debate.proposition}.`);
  lines.push(`Speaking for the opposition: ${debate.opposition}.`);
  lines.push(`Your chief adjudicator in Room ${debate.room} is ${debate.adjudicator}.`);
  const label = describeFormat(debate.format);
  lines.push(`Rules of this debate follow the ${label} format.`);
  if (isIronPerson(debate.format)) {
    lines.push(`Note: a speaker is debating alone in Room ${debate.room}.`);
  }
  return lines;
}

function announce(debates) {
  if (!Array.isArray(debates)) {
    throw new TypeError(`announce expects a list of debates, received ${typeof debates}.`);
  }
  const total = debates.length;
  const lines = ['All debaters, please report to the main hall.'];
  lines.push(`There are ${total} matches scheduled in this round.`);
  debates.forEach((debate, index) => {
    lines.push(...describeMatch(debate, index));
  });
  lines.push(`Preparation time has now started for all ${total} matches.`);
  lines.push('The best of luck to all teams.');
  return lines.join('\n');
}

function main() {
  const schedule = [
    {
      room: '101',
      motion: 'This House would ban plastic bags',
      proposition: 'Team Alpha',
