      motion: 'This House would tax private jets',
      proposition: 'Team Gamma',
      opposition: 'Team Delta',
      adjudicator: 'Omar',
      format: 'iron person'
    }
  ];
  console.log(announce(schedule));
}

main();

module.exports = { announce, describeMatch, describeFormat, isIronPerson };

