const DIRECTION_LABELS = { lat: ['N', 'S'], lon: ['E', 'W'] };

function formatCoordinate(value, axis) {
  const [positive, negative] = DIRECTION_LABELS[axis];
  const hemisphere = value >= 0 ? positive : negative;
  return `${Math.abs(value).toFixed(4)}° ${hemisphere}`;
}

function validateWaypoint(waypoint, index) {
  const numericFields = ['latitude', 'longitude', 'altitude', 'speed', 'cameraAngle'];
  for (const field of numericFields) {
    if (typeof waypoint[field] !== 'number' || Number.isNaN(waypoint[field])) {
      throw new TypeError(`Waypoint ${index + 1} has an invalid ${field} value.`);
    }
  }
  if (typeof waypoint.action !== 'string' || waypoint.action.trim() === '') {
    throw new TypeError(`Waypoint ${index + 1} is missing an action description.`);
  }
}

function describeWaypoint(waypoint, index) {
  validateWaypoint(waypoint, index);
  const label = `waypoint ${index + 1}`;
  const latitude = formatCoordinate(waypoint.latitude, 'lat');
  const longitude = formatCoordinate(waypoint.longitude, 'lon');
  const batteryDrain = waypoint.speed * 2;
  return [
    `Fly to ${label} at ${latitude}, ${longitude}.`,
    `Climb to a cruise altitude of ${waypoint.altitude} meters.`,
    `Maintain a flight speed of ${waypoint.speed} meters per second.`,
    `Perform the action: ${waypoint.action}.`,
    `Tilt the camera to ${waypoint.cameraAngle} degrees.`,
    `Estimated battery drain for this leg is ${batteryDrain} percent.`
  ];
}

function plan(waypoints) {
  if (!Array.isArray(waypoints)) {
    throw new TypeError('plan() expects an array of waypoint objects.');
  }
  const lines = [`Flight plan contains ${waypoints.length} waypoints.`];
  waypoints.forEach((waypoint, index) => {
    lines.push(...describeWaypoint(waypoint, index));
  });
  lines.push('The drone returns to base.');
  return lines;
}

function renderPlan(waypoints) {
  return plan(waypoints)
    .map((line, index) => `${String(index + 1).padStart(2, ' ')}. ${line}`)
    .join('\n');
}

const mission = [
  { latitude: 48.8584, longitude: 2.2945, altitude: 60, speed: 8, action: 'photograph the tower base', cameraAngle: 45 },
  { latitude: 48.8606, longitude: 2.3376, altitude: 85, speed: 12, action: 'scan the courtyard', cameraAngle: 30 },
  { latitude: -33.8568, longitude: 151.2153, altitude: 120, speed: 15, action: 'record a panoramic sweep', cameraAngle: 0 }
];

const totalDrain = mission.reduce((sum, waypoint) => sum + waypoint.speed * 2, 0);
console.log(renderPlan(mission));
console.log(`Total estimated battery drain: ${totalDrain} percent.`);

module.exports = { plan, renderPlan, formatCoordinate };

