function formatDepth(value) {
  return `${value.toFixed(1)} m`;
}

function validateLayer(layer, index) {
  if (typeof layer.rockType !== 'string' || layer.rockType.length === 0) {
    throw new Error(`Layer ${index + 1} is missing a rock type`);
  }
  if (!Number.isFinite(layer.startDepth) || !Number.isFinite(layer.endDepth)) {
    throw new Error(`Layer ${index + 1} has non-numeric depth boundaries`);
  }
  if (layer.endDepth < layer.startDepth) {
    const range = `${layer.startDepth} to ${layer.endDepth}`;
    throw new Error(`Layer ${index + 1} ends above its start (${range})`);
  }
}

function describeLayer(layer, index) {
  const position = `Layer ${index + 1}`;
  const thickness = layer.endDepth - layer.startDepth;
  return [
    `${position}: rock type is ${layer.rockType}.`,
    `Its color is recorded as ${layer.color}.`,
    `The layer begins at a depth of ${formatDepth(layer.startDepth)}.`,
    `The layer ends at a depth of ${formatDepth(layer.endDepth)}.`,
    `Its total thickness measures ${formatDepth(thickness)}.`,
    `Fossil inclusions: ${layer.fossils}; grain size: ${layer.grainSize}.`,
  ];
}

function document(strata) {
  if (!Array.isArray(strata)) {
    throw new TypeError(`Expected an array of layers, received ${typeof strata}`);
  }
  const lines = [`Core analysis of ${strata.length} rock layers.`];
  strata.forEach((layer, index) => {
    validateLayer(layer, index);
    lines.push(...describeLayer(layer, index));
  });
  lines.push('Analysis complete.');
  return lines;
}

function main() {
  const core = [
    {
      rockType: 'sandstone',
      startDepth: 0,
      endDepth: 12.5,
      color: 'pale yellow',
      fossils: 'shell fragments',
      grainSize: 'medium',
    },
    {
      rockType: 'shale',
      startDepth: 12.5,
      endDepth: 30,
      color: 'dark grey',
      fossils: 'plant impressions',
      grainSize: 'very fine',
    },
    {
      rockType: 'limestone',
      startDepth: 30,
      endDepth: 47.25,
      color: 'off white',
      fossils: 'crinoid stems',
      grainSize: 'fine',
    },
  ];
  const report = document(core);
  report.forEach((line) => console.log(line));
  const total = core[core.length - 1].endDepth - core[0].startDepth;
  console.log(`Total cored interval: ${formatDepth(total)}.`);
}

main();

