    species: 'Welwitschia mirabilis',
    family: 'Welwitschiaceae',
    region: 'Namib Desert, Namibia',
    collector: 'H. Okuru',
    year: 2001,
    preservation: 'freeze-dried',
  },
];

console.log(label(collection).join('\n'));

