function validateUnit(unit, index) {
  const label = `Unit #${index + 1}`;
  if (!unit || typeof unit.name !== 'string' || unit.name.trim() === '') {
    throw new Error(`${label} is missing a unit name.`);
  }
  for (const field of ['models', 'points', 'baseSize']) {
    if (typeof unit[field] !== 'number' || !Number.isFinite(unit[field])) {
      throw new Error(`${label} (${unit.name}) has an invalid ${field} value.`);
    }
  }
  if (typeof unit.weapon !== 'string' || typeof unit.rule !== 'string') {
    throw new Error(`${label} (${unit.name}) needs both a weapon and a rule as text.`);
  }
  return unit;
}

function pluralModels(count) {
  return count === 1 ? 'model' : 'models';
}

function describeUnit(unit) {
  const lines = [];
  lines.push(`Unit: ${unit.name}`);
  lines.push(`Strength: ${unit.models} ${pluralModels(unit.models)} on the field.`);
  lines.push(`Cost: ${unit.points} points in total.`);
  lines.push(`Equipped with: ${unit.weapon}.`);
  lines.push(`Special rule: ${unit.rule}.`);
  lines.push(`Basing: every model must stand on a ${unit.baseSize}mm base.`);
  return lines;
}

function muster(units) {
  if (!Array.isArray(units)) {
    throw new TypeError(`muster expects an array of unit records, got ${typeof units}.`);
  }
  const roster = units.map(validateUnit);
  const report = [`The army is composed of ${roster.length} units.`];
  for (const unit of roster) {
    report.push(...describeUnit(unit));
  }
  report.push('Inspection complete. Fall out!');
  return report;
}

function pointsTotal(units) {
  return units.reduce((sum, unit) => sum + unit.points, 0);
}

function main() {
  const army = [
    { name: 'Grenadier Squad', models: 10, points: 150, weapon: 'lasrifles', rule: 'they never break formation', baseSize: 25 },
    { name: 'Iron Sentinel', models: 1, points: 210, weapon: 'a siege cannon', rule: 'it ignores cover saves', baseSize: 60 },
    { name: 'Wyrm Riders', models: 5, points: 185, weapon: 'lances and shields', rule: 'they charge twice as far', baseSize: 40 }
  ];

  for (const line of muster(army)) {
    console.log(line);
  }
  console.log(`Army total: ${pointsTotal(army)} points.`);

  const illegal = [{ name: 'Ghost Legion', models: 'many', points: 300, weapon: 'spears', rule: 'fear', baseSize: 32 }];
  try {
    muster(illegal);
  } catch (err) {
    console.log(`Roster rejected: ${err.message}`);
  }
}

main();

module.exports = { muster, describeUnit, pointsTotal };

