'use strict';

const DEPTH_SEPARATOR = '-';

function normalizeDepths(sequence) {
  return String(sequence)
    .split(/[^0-9]+/)
    .filter((step) => step.length > 0)
    .join(DEPTH_SEPARATOR);
}

function validateKey(key, index) {
  const position = `key record #${index + 1}`;
  if (!key.reference || !String(key.reference).trim()) {
    throw new Error(`Missing customer reference on ${position}.`);
  }
  if (!key.profile || !String(key.profile).trim()) {
    throw new Error(`Missing keyway profile on ${position}.`);
  }
  const depths = normalizeDepths(key.depths);
  const cuts = depths ? depths.split(DEPTH_SEPARATOR).length : 0;
  if (cuts !== Number(key.pins)) {
    const detail = `${cuts} depth(s) for ${Number(key.pins)} pin(s)`;
    throw new Error(`Depth sequence mismatch on ${position}: ${detail}.`);
  }
  if (!Number.isInteger(Number(key.copies)) || Number(key.copies) < 1) {
    throw new Error(`Duplicate count must be a positive integer on ${position}.`);
  }
  return depths;
}

function cut(keys) {
  const instructions = [`Firing up the cutting machine for ${keys.length} job(s).`];
  let blanks = 0;
  keys.forEach((key, index) => {
    const depths = validateKey(key, index);
    blanks += Number(key.copies);
    instructions.push(`Customer reference: ${String(key.reference).trim()}.`);
    instructions.push(`Mount a ${String(key.profile).trim()} keyway blank.`);
    instructions.push(`Pin count is ${Number(key.pins)}.`);
    instructions.push(`Set the spacing offset to ${Number(key.offset)} mm.`);
    instructions.push(`Follow the cut depth sequence ${depths}.`);
    instructions.push(`Cut ${Number(key.copies)} duplicate(s).`);
  });
  instructions.push(`Turning off the machine after ${blanks} blank(s).`);
  return instructions;
}

function printGuide(keys) {
  let lines;
  try {
    lines = cut(keys);
  } catch (error) {
    console.error(`Cutting guide rejected: ${error.message}`);
    return;
  }
  lines.forEach((line, index) => {
    const step = String(index + 1).padStart(3, ' ');
    console.log(step + '  ' + line);
  });
}

