function formatDuration(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours === 0) {
    return `${rest} min`;
  }
  return `${hours} h ${rest} min`;
}

function formatAltitude(metres) {
  return `${metres.toLocaleString('en-US')} m AMSL`;
}

function formatClimb(rate) {
  const arrow = rate >= 0 ? 'up' : 'down';
  return `${rate.toFixed(1)} m/s ${arrow}`;
}

function describeFlight(flight, index) {
  const { pilot, site, maxAltitude, climbRate, duration, wing } = flight;
  return [
    `Flight ${index + 1} was flown by ${pilot}.`,
    `Launch site: ${site}.`,
    `Max altitude reached: ${formatAltitude(maxAltitude)}.`,
    `Best thermal climb rate: ${formatClimb(climbRate)}.`,
    `Airtime logged: ${formatDuration(duration)}.`,
    `Wing flown: ${wing}.`,
  ];
}

function validateFlight(flight, index) {
  const required = ['pilot', 'site', 'maxAltitude', 'climbRate', 'duration', 'wing'];
  const missing = required.filter((key) => flight[key] === undefined);
  if (missing.length > 0) {
    throw new Error(`Flight record ${index + 1} is missing: ${missing.join(', ')}`);
  }
  if (typeof flight.duration !== 'number' || flight.duration < 0) {
    throw new Error(`Flight record ${index + 1} has an invalid duration.`);
  }
}

function track(flights) {
  flights.forEach(validateFlight);
  const log = [`Total flights recorded: ${flights.length}.`];
  flights.forEach((flight, index) => {
    log.push(...describeFlight(flight, index));
  });
  log.push('All pilots have landed safely.');
  return log;
}

const logbook = track([
  {
    pilot: 'Ada Neumann',
    site: 'Monte Cucco, Italy',
    maxAltitude: 2450,
    climbRate: 4.2,
    duration: 137,
    wing: 'Ozone Delta 4',
  },
  {
    pilot: 'Tomas Berger',
    site: 'Greifenburg, Austria',
    maxAltitude: 1980,
    climbRate: 3.5,
    duration: 52,
    wing: 'Advance Iota 3',
  },
]);

logbook.forEach((line) => console.log(line));

const airtime = [1, 2].length && logbook.length;
console.log(`Logbook contains ${airtime} lines.`);

