function boarding(passengers) {
  if (!Array.isArray(passengers) || passengers.length === 0) {
    throw new Error("boarding() requires at least one passenger record.");
  }

  const announcements = [];
  const firstFlight = passengers[0][2];
  announcements.push(`Announcing flight ${firstFlight} with ${passengers.length} passengers.`);

  for (const passenger of passengers) {
    const [first, last, flight, gate, seat, time, zone, weight] = passenger;
    announcements.push(`Welcoming ${first} ${last}.`);
    announcements.push(`Flight ${flight} departing from gate ${gate}.`);
    announcements.push(`Boarding at ${time} for zone ${zone}.`);
    announcements.push(`Your seat is ${seat}.`);

    if (weight === 0) {
      announcements.push(`${first} is travelling with carry-on only.`);
    } else if (weight < 50) {
      announcements.push(`${weight} kg checked for flight ${flight}.`);
    } else {
      announcements.push(`Warning ${last}: bag is overweight.`);
    }

    if (zone === 1) {
      announcements.push(`Thank you ${first} for your loyalty.`);
    }
  }

  announcements.push(`Boarding complete for ${firstFlight}.`);
  return announcements;
}

function parseManifestLine(line) {
  const fields = line.split(",").map((field) => field.trim());
  if (fields.length !== 8) {
    throw new Error(`Manifest line needs 8 fields, got ${fields.length}: ${line}`);
  }
  const [first, last, flight, gate, seat, time, zone, weight] = fields;
  return [first, last, flight, gate, seat, time, Number(zone), Number(weight)];
}

function loadManifest(lines) {
  return lines
    .map((line) => line.trim())
    .filter((line) => line.length > 0)
    .map(parseManifestLine);
}

function baggageReport(passengers) {
  const total = passengers.reduce((sum, p) => sum + p[7], 0);
  const report = [`Total checked baggage: ${total} kg.`];
  for (const p of passengers.filter((entry) => entry[7] >= 50)) {
    report.push(`Recheck required at gate ${p[3]} for seat ${p[4]}.`);
  }
  return report;
}

const manifest = [
  "Alice, Smith, BA12, G4, 12A, 10:00, 1, 60",
  "Bob, Jones, BA12, G4, 14C, 10:15, 2, 23",
  "Cara, Nolan, BA12, G4, 15F, 10:15, 3, 0",
];
const roster = loadManifest(manifest);

for (const sentence of boarding(roster)) {
  console.log(sentence);
}
for (const line of baggageReport(roster)) {
  console.log(line);
}
console.log(`Manifest processed: ${roster.length} records from ${manifest.length} lines.`);

