function validateEvent(event, index) {
  if (!Array.isArray(event) || event.length !== 5) {
    throw new Error(`Event ${index} must list category, room, action, time and battery.`);
  }
  const battery = event[4];
  if (typeof battery !== "number" || Number.isNaN(battery)) {
    throw new Error(`Event ${index} has an unreadable battery level: ${battery}.`);
  }
  return event;
}

function describeCategory(category, room) {
  if (category === "lighting") {
    return `Illuminating the ${room}.`;
  }
  if (category === "climate") {
    return `Adjusting the temperature of the ${room}.`;
  }
  return `Running a generic action on the ${category}.`;
}

function batteryWarning(category, room, battery) {
  if (battery < 20) {
    return `Warning: ${room} ${category} has low battery.`;
  }
  return null;
}

function routine(events) {
  const total = events.length;
  const lines = [`Scheduled ${total} events.`];

  events.forEach((event, index) => {
    const [category, room, action, time, battery] = validateEvent(event, index);

    lines.push(`The ${category} activated in the ${room}.`);
    lines.push(`Action ${action} occurred at ${time}.`);
    lines.push(`The ${room} synced at ${time}.`);
    lines.push(describeCategory(category, room));

    const warning = batteryWarning(category, room, battery);
    if (warning) {
      lines.push(warning);
    }
  });

  lines.push(`Routine finished ${total} events.`);
  return lines;
}

function report(events) {
  const lines = routine(events);
  const numbered = lines.map((line, i) => `${String(i + 1).padStart(2, " ")}. ${line}`);
  return numbered.join("\n");
}

const schedule = [
  ["lighting", "kitchen", "on", "08:00", 15],
  ["climate", "bedroom", "warm", "21:30", 64],
  ["speaker", "hallway", "chime", "07:45", 8]
];

console.log(report(schedule));

const lowBattery = schedule.filter(([, , , , battery]) => battery < 20);
console.log(`${lowBattery.length} of ${schedule.length} devices need charging soon.`);

for (const [category, room] of lowBattery) {
  console.log(`Service the ${category} in the ${room}.`);
}

