function formatDuration(seconds) {
  if (seconds < 60) {
    return `${seconds} seconds`;
  }
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  const base = `${minutes} min`;
  return rest === 0 ? base : `${base} ${rest} s`;
}

function validateStep(step, index) {
  if (!Array.isArray(step) || step.length !== 5) {
    throw new TypeError(`Step ${index + 1} must have 5 fields, got ${step && step.length}.`);
  }
  const [station, part, operation, duration, condition] = step;
  if (typeof duration !== "number" || Number.isNaN(duration)) {
    throw new TypeError(`Step ${index + 1} has a non-numeric duration: ${duration}.`);
  }
  return { station, part, operation, duration, condition: String(condition).toLowerCase() };
}

function conditionSentence({ station, part, operation, condition }) {
  if (condition === "cold") {
    return `${part} is chilling.`;
  }
  if (condition === "hot") {
    return `Warning: ${station} is heating up.`;
  }
  if (condition === "ambient") {
    return `Normal conditions for ${operation}.`;
  }
  return null;
}

function assembly(steps) {
  const total = steps.length;
  const log = [`Starting line for ${total} steps.`];

  steps.forEach((raw, index) => {
    const step = validateStep(raw, index);
    log.push(`${step.part} arrived at ${step.station}.`);
    log.push(`Operation ${step.operation} taking ${step.duration} seconds.`);
    log.push(`${step.station} finished ${step.part}.`);

    const note = conditionSentence(step);
    if (note !== null) {
      log.push(note);
    }
    if (step.duration > 100) {
      log.push(`Delay: ${step.part} taking extra time.`);
    }
  });

  log.push(`Line shut down after ${total} steps.`);
  return log;
}

function report(steps) {
  const log = assembly(steps);
  const totalSeconds = steps.reduce((sum, step) => sum + step[3], 0);
  const lines = log.map((sentence, i) => `${String(i + 1).padStart(2, " ")}. ${sentence}`);
  lines.push(`Total line time: ${formatDuration(totalSeconds)}.`);
  return lines.join("\n");
}

const shift = [
  ["S1", "Gear", "weld", 120, "hot"],
  ["S2", "Bearing", "press", 45, "cold"],
  ["S3", "Housing", "inspect", 90, "ambient"],
];

console.log(report(shift));

