function transit(stations) {
  if (!Array.isArray(stations) || stations.length === 0) {
    throw new TypeError('transit requires a non-empty list of stations.');
  }
  const announcements = [];
  const firstLine = stations[0][1];
  announcements.push(`Welcome aboard ${firstLine} for ${stations.length} stations.`);

  stations.forEach((station, index) => {
    const [name, line, minutes, side, accessible] = validateStation(station, index);
    announcements.push(`${line} arriving at ${name} in ${minutes} minutes.`);
    announcements.push(`Exit ${side} at ${name}.`);
    announcements.push(`Welcome to ${name} on ${line}.`);
    announcements.push(arrivalNotice(name, minutes));
    if (accessible) {
      announcements.push(`Accessible boarding at ${name}.`);
    }
  });

  announcements.push(`Thank you for riding ${firstLine}.`);
  return announcements;
}

function validateStation(station, index) {
  if (!Array.isArray(station) || station.length !== 5) {
    throw new TypeError(`Station at position ${index} must have exactly 5 fields.`);
  }
  const [name, line, minutes, side, accessible] = station;
  if (typeof name !== 'string' || typeof line !== 'string' || typeof side !== 'string') {
    throw new TypeError(`Station ${index} needs string name, line and side values.`);
  }
  if (!Number.isInteger(minutes) || minutes < 0) {
    throw new RangeError(`Arrival minutes for ${name} must be a non-negative integer.`);
  }
  if (typeof accessible !== 'boolean') {
    throw new TypeError(`Wheelchair access for ${name} must be a boolean.`);
  }
  return [name, line, minutes, side, accessible];
}

function arrivalNotice(name, minutes) {
  if (minutes === 0) {
    return `Train now at ${name}.`;
  }
  if (minutes === 1) {
    return `Train approaching ${name}.`;
  }
  return `Please wait ${minutes} minutes.`;
}

function formatScript(announcements) {
  return announcements
    .map((line, index) => `${String(index + 1).padStart(2, ' ')}. ${line}`)
    .join('\n');
}

function main() {
  const route = [
    ['Central', 'Red', 1, 'left', true],
    ['Harbour', 'Red', 4, 'right', false],
    ['Museum', 'Red', 0, 'left', true],
  ];
  const announcements = transit(route);
  console.log(formatScript(announcements));
  console.log(`Total announcements: ${announcements.length}`);

  try {
    transit([['Broken', 'Blue', -2, 'left', false]]);
  } catch (error) {
    console.log(`Rejected route: ${error.message}`);
  }
}

main();

module.exports = { transit, formatScript };

