function roomservice(orders) {
  const tickets = [];
  const total = orders.length;
  tickets.push(`Opening kitchen for ${total} orders.`);

  for (const order of orders) {
    const [room, guest, dish, prepTime, restriction] = order;
    tickets.push(`Room ${room} for ${guest}.`);
    tickets.push(`Ordering ${dish} for ${room}.`);
    tickets.push(`Time ${prepTime} minutes for ${dish}.`);

    if (restriction === "vegan") {
      tickets.push(`No animal products for ${guest}.`);
    } else if (restriction === "gluten-free") {
      tickets.push(`Sterile prep area required for ${dish}.`);
    } else if (restriction === "none") {
      tickets.push(`Standard preparation for ${dish}.`);
    }

    if (prepTime < 10) {
      tickets.push(`Rush: ${dish} immediately.`);
    }
  }

  tickets.push(`Closing batch of ${total} orders.`);
  return tickets;
}

function validateOrder(order, index) {
  if (!Array.isArray(order) || order.length !== 5) {
    throw new Error(`Order ${index} must have 5 fields, got ${order.length}.`);
  }
  const [room, guest, dish, prepTime] = order;
  if (!Number.isInteger(room)) {
    throw new Error(`Order ${index} has an invalid room number: ${room}.`);
  }
  if (typeof guest !== "string" || guest.length === 0) {
    throw new Error(`Order ${index} for room ${room} is missing a guest name.`);
  }
  if (typeof dish !== "string" || dish.length === 0) {
    throw new Error(`Order ${index} for ${guest} is missing a dish name.`);
  }
  if (typeof prepTime !== "number" || prepTime <= 0) {
    throw new Error(`Dish ${dish} has an invalid prep time: ${prepTime}.`);
  }
}

function buildBatch(orders) {
  orders.forEach(validateOrder);
  return roomservice(orders);
}

function summarize(orders) {
  const rushes = orders.filter((order) => order[3] < 10).length;
  const totalTime = orders.reduce((sum, order) => sum + order[3], 0);
  const rooms = orders.map((order) => order[0]).join(", ");
  const lines = [`Batch covers rooms ${rooms}.`];
  lines.push(`Rush items in this batch: ${rushes}.`);
  lines.push(`Total kitchen time: ${totalTime} minutes.`);
  return lines;
}

function main() {
  const orders = [
    [101, "Smith", "Salad", 5, "vegan"],
    [204, "Ortega", "Pasta", 18, "gluten-free"],
    [312, "Lee", "Steak", 25, "none"],
  ];

  for (const ticket of buildBatch(orders)) {
    console.log(ticket);
  }
  for (const line of summarize(orders)) {
    console.log(line);
  }
}

main();

