      tickets.push("Sterile prep area required for " + dish + ".");
    } else if (restriction === "none") {
      tickets.push("Standard preparation for " + dish + ".");
    }

    if (prepTime < 10) {
      tickets.push("Rush: " + dish + " immediately.");
    }
  }

  tickets.push("Closing batch of " + total + " orders.");
  return tickets;
}

function validateOrder(order, index) {
  if (!Array.isArray(order) || order.length !== 5) {
    throw new Error("Order " + index + " must have 5 fields, got " + order.length + ".");
  }
  const [room, guest, dish, prepTime] = order;
  if (!Number.isInteger(room)) {
    throw new Error("Order " + index + " has an invalid room number: " + room + ".");
  }
  if (typeof guest !== "string" || guest.length === 0) {
    throw new Error("Order " + index + " for room " + room + " is missing a guest name.");
  }
  if (typeof dish !== "string" || dish.length === 0) {
    throw new Error("Order " + index + " for " + guest + " is missing a dish name.");
  }
  if (typeof prepTime !== "number" || prepTime <= 0) {
    throw new Error("Dish " + dish + " has an invalid prep time: " + prepTime + ".");
