function validateMessage(entry, index) {
  if (!Array.isArray(entry) || entry.length !== 5) {
    throw new Error(`Message ${index + 1} must have five fields.`);
  }
  const [origin, recipient, words, cost, encryption] = entry;
  if (typeof origin !== 'string' || origin.length === 0) {
    throw new Error(`Message ${index + 1} has an empty sender location.`);
  }
  if (typeof recipient !== 'string' || recipient.length === 0) {
    throw new Error(`Message ${index + 1} has an empty recipient name.`);
  }
  if (!Number.isFinite(words) || words <= 0) {
    throw new Error(`Word count for ${recipient} must be a positive number.`);
  }
  if (!Number.isFinite(cost) || cost < 0) {
    throw new Error(`Transmission cost for ${recipient} cannot be negative.`);
  }
  const kind = String(encryption).toLowerCase();
  if (!['military', 'commercial', 'cleartext'].includes(kind)) {
    throw new Error(`Unknown encryption type "${encryption}" for ${recipient}.`);
  }
  return { origin, recipient, words, cost, encryption: kind };
}

function encryptionLine(message) {
  const { origin, recipient, encryption } = message;
  if (encryption === 'military') {
    return `Top secret handling for ${recipient}.`;
  }
  if (encryption === 'commercial') {
    return `Business priority for ${origin}.`;
  }
  return `Standard routing to ${recipient}.`;
}

function telex(messages) {
  if (!Array.isArray(messages)) {
    throw new TypeError('telex expects an array of message lists.');
  }
  const total = messages.length;
  const lines = [`Wire open for ${total} messages.`];
  messages.forEach((entry, index) => {
    const message = validateMessage(entry, index);
    const { origin, recipient, words, cost } = message;
    lines.push(`${origin} dispatching to ${recipient}.`);
    lines.push(`Billing ${cost} for ${words} words.`);
    lines.push(`Routing ${words} words to ${recipient}.`);
    lines.push(encryptionLine(message));
    if (cost > 50) {
      lines.push(`Audit flagged for ${origin}.`);
    }
  });
  lines.push(`Wire closed after ${total} messages.`);
  return lines;
}

function report(messages) {
  const lines = telex(messages);
  const billed = messages.reduce((sum, entry) => sum + entry[3], 0);
  const words = messages.reduce((sum, entry) => sum + entry[2], 0);
  const body = lines.map((line, index) => `${index + 1}. ${line}`).join('\n');
  return `${body}\nTotal ${billed} charged for ${words} words.`;
}

function main() {
  const traffic = [
    ['London', 'Jones', 100, 60, 'military'],
    ['Paris', 'Dupont', 40, 12, 'commercial'],
    ['Cairo', 'Hassan', 75, 51, 'cleartext'],
  ];
  console.log(report(traffic));
  try {
    telex([['Lisbon', 'Silva', 0, 5, 'cleartext']]);
  } catch (error) {
    console.log(`Rejected: ${error.message}`);
  }
}

main();

module.exports = { telex, report, validateMessage, encryptionLine };

