function docket(hearings) {
  const total = hearings.length;
  const lines = [`Court in session for ${total} hearings.`];

  for (const hearing of hearings) {
    const [caseNumber, defendant, charge, trialDay, custody] = hearing;

    lines.push(`Case ${caseNumber} for ${defendant}.`);
    lines.push(`Charge ${charge} against ${defendant}.`);
    lines.push(`Day ${trialDay} for ${caseNumber}.`);

    if (custody === 'remanded') {
      lines.push(`${defendant} returns to jail.`);
    } else if (custody === 'bailed') {
      lines.push(`Temporary freedom despite ${charge}.`);
    } else if (custody === 'released') {
      lines.push(`Case ${caseNumber} closed.`);
    }

    if (trialDay === 1) {
      lines.push(`Opening statements for ${defendant}.`);
    }
  }

  lines.push(`Court adjourned for ${total} hearings.`);
  return lines;
}

function validateHearings(hearings) {
  if (!Array.isArray(hearings)) {
    throw new TypeError('docket expects an array of hearing records.');
  }
  hearings.forEach((hearing, index) => {
    if (!Array.isArray(hearing) || hearing.length !== 5) {
      throw new TypeError(`Hearing ${index + 1} must have exactly five fields.`);
    }
    const day = hearing[3];
    if (!Number.isInteger(day) || day < 1) {
      throw new RangeError(`Trial day for case ${hearing[0]} must be a positive integer.`);
    }
  });
  return hearings;
}

function custodyTally(hearings) {
  return hearings.reduce((tally, [, , , , custody]) => {
    tally[custody] = (tally[custody] || 0) + 1;
    return tally;
  }, {});
}

function formatDocket(hearings) {
  const sentences = docket(validateHearings(hearings));
  const numbered = sentences.map((sentence, i) => `${String(i + 1).padStart(3, ' ')}. ${sentence}`);
  const tally = custodyTally(hearings);
  const breakdown = Object.keys(tally)
    .sort()
    .map((status) => `${status}: ${tally[status]}`)
    .join(', ');
  numbered.push(`Custody breakdown -> ${breakdown || 'none'}`);
  return numbered.join('\n');
}

function main() {
  const hearings = [
    ['99X', 'Doe', 'Theft', 1, 'remanded'],
    ['104B', 'Marlowe', 'Fraud', 3, 'bailed'],
    ['221C', 'Okonkwo', 'Trespass', 2, 'released'],
  ];

  console.log(formatDocket(hearings));

  try {
    formatDocket([['777Z', 'Vance', 'Arson', 0, 'bailed']]);
  } catch (err) {
    console.error(`Docket rejected: ${err.message}`);
  }
}

main();

module.exports = { docket, formatDocket, validateHearings, custodyTally };

