function validateTask(task, index) {
  if (!Array.isArray(task) || task.length !== 5) {
    throw new TypeError(`Task ${index + 1} must have 5 fields: crew, module, tool, minutes, tether.`);
  }
  const [crew, module, tool, minutes, tether] = task;
  if (typeof minutes !== "number" || Number.isNaN(minutes)) {
    throw new TypeError(`Task ${index + 1} has a non-numeric duration: ${minutes}.`);
  }
  return { crew, module, tool, minutes, tether };
}

function tetherLine(crew, module, minutes, tether) {
  const mode = String(tether).toLowerCase();
  if (mode === "double") {
    return `Dual anchor ordered for ${crew}.`;
  }
  if (mode === "single") {
    return `Standard clip confirmed on ${module}.`;
  }
  if (mode === "none") {
    return `Free float authorized for ${minutes} minutes.`;
  }
  throw new RangeError(`Unknown tether requirement "${tether}" for ${crew}.`);
}

function spacewalk(tasks) {
  if (!Array.isArray(tasks)) {
    throw new TypeError("spacewalk expects an array of task lists.");
  }
  const total = tasks.length;
  const lines = [`Airlock open for ${total} tasks.`];

  tasks.forEach((task, index) => {
    const { crew, module, tool, minutes, tether } = validateTask(task, index);
    lines.push(`${crew} assigned to ${module}.`);
    lines.push(`${crew} use the ${tool}.`);
    lines.push(`Allocated ${minutes} minutes for ${module}.`);
    lines.push(tetherLine(crew, module, minutes, tether));
    if (minutes > 60) {
      lines.push(`Hydrate reminder for ${crew}.`);
    }
  });

  lines.push(`Return to airlock after ${total} tasks.`);
  return lines;
}

function missionLog(tasks) {
  const lines = spacewalk(tasks);
  const width = String(lines.length).length;
  return lines
    .map((line, i) => `[${String(i + 1).padStart(width, "0")}] ${line}`)
    .join("\n");
}

function main() {
