function parseSensor(sensor, index) {
  if (!Array.isArray(sensor) || sensor.length !== 5) {
    throw new TypeError(`Sensor entry ${index} must hold exactly 5 fields.`);
  }
  const [name, zone, code, latency, calibrated] = sensor;
  if (!Number.isFinite(latency)) {
    throw new TypeError(`Latency for ${name} must be a finite number.`);
  }
  return {
    name: String(name),
    zone: String(zone),
    code: String(code).toLowerCase(),
    latency,
    calibrated: Boolean(calibrated),
  };
}

function verdictLine(code, name, zone) {
  if (code === 'active') {
    return `Nominal operation for ${name}.`;
