function phraseFor(action, subject) {
  return `${action} for ${subject}.`;
}

function validateTarget(target, index) {
  if (!Array.isArray(target) || target.length !== 5) {
    throw new TypeError(`Target ${index + 1} must be a list of five fields.`);
  }
  const [body, rightAscension, declination, observer] = target;
  if (typeof body !== "string" || body.length === 0) {
    throw new TypeError(`Target ${index + 1} is missing a celestial body name.`);
  }
  if (!Number.isFinite(rightAscension)) {
    throw new TypeError(`Right ascension for ${body} must be a finite number.`);
  }
  if (!Number.isFinite(declination)) {
    throw new TypeError(`Declination for ${body} must be a finite number.`);
  }
  if (typeof observer !== "string" || observer.length === 0) {
    throw new TypeError(`Observer for ${body} must be a name.`);
  }
}

function declinationLine(body, declination, observer) {
  if (declination < 0) {
    return phraseFor("Pointing south", body);
  }
  if (declination === 0) {
    return phraseFor("Locking on the equator", observer);
  }
  return `Pointing north to ${declination}.`;
}

function observatory(targets) {
  if (!Array.isArray(targets)) {
    throw new TypeError("targets must be an array of target lists.");
  }
  const total = targets.length;
  const lines = [`Dome open for ${total} targets.`];
  targets.forEach((target, index) => {
    validateTarget(target, index);
    const [body, rightAscension, declination, observer, deepSpace] = target;
    lines.push(phraseFor(`Aligning ${rightAscension}`, body));
    lines.push(phraseFor(`Tilting to ${declination}`, observer));
    lines.push(phraseFor(`Tracking ${body}`, observer));
    lines.push(declinationLine(body, declination, observer));
    if (deepSpace) {
      lines.push(phraseFor("Engaging long exposure mode", body));
    }
  });
  lines.push(`Parking telescope after ${total} targets.`);
  return lines;
}

function numberedSchedule(targets) {
  return observatory(targets).map((line, index) => {
    const number = `${index + 1}`.padStart(2, " ");
    return `${number}. ${line}`;
  });
}

const tonight = [
  ["Mars", 12, -5, "Bob", false],
  ["Andromeda", 1, 0, "Ada", true],
  ["Vega", 18, 38, "Lin", false],
];

console.log(numberedSchedule(tonight).join("\n"));

