function normalizeCondition(condition) {
  const cleaned = String(condition).trim().toLowerCase();
  if (!cleaned) {
    throw new Error('Every inspection needs a track condition.');
  }
  return cleaned;
}

function validateInspection(inspection, index) {
  const { segment, gradient, tension, condition } = inspection;
  if (!segment) {
    throw new Error(`Inspection #${index + 1} is missing a segment identifier.`);
  }
  if (!Number.isFinite(Number(gradient))) {
    throw new Error(`Segment ${segment} has a non-numeric gradient percentage.`);
  }
  if (!tension) {
    throw new Error(`Segment ${segment} has no recorded cable tension.`);
  }
  return {
    segment,
    gradient: Number(gradient),
    tension: String(tension),
    condition: normalizeCondition(condition)
  };
}

function report(inspections) {
  const sentences = [];
  inspections.forEach((raw, index) => {
    const { segment, gradient, tension, condition } = validateInspection(raw, index);
    sentences.push(`Segment ${segment} is currently ${condition}.`);
    if (condition === 'clear') {
      sentences.push(`The ${condition} track has a ${gradient} percent gradient.`);
      sentences.push(`Validate the running rails on segment ${segment}.`);
    } else if (condition === 'worn') {
      sentences.push(`Adjust the ${gradient} percent climb because the rails are ${condition}.`);
      sentences.push(`Lubricate the haulage cable across segment ${segment}.`);
    } else if (condition === 'severe') {
      sentences.push(`Replace the ${gradient} percent section rated as ${condition}.`);
      sentences.push(`Emergency crews must confirm the cable tension is ${tension}.`);
    }
    if (gradient > 40) {
      sentences.push(`Anchor segment ${segment} again, the ${gradient} percent grade exceeds forty.`);
    }
  });
  return sentences;
}

function summarize(inspections) {
  const steepest = inspections.reduce(
    (worst, item) => (Number(item.gradient) > Number(worst.gradient) ? item : worst),
    inspections[0]
  );
  const header = `Maintenance script for ${inspections.length} track segments.`;
  const focus = `Steepest climb: segment ${steepest.segment} at ${steepest.gradient} percent.`;
  return [header, focus];
}

