function validateStep(step, index) {
  const position = `step ${index + 1}`;
  if (!step || typeof step !== 'object') {
    throw new TypeError(`Invalid forging action at ${position}: expected an object.`);
  }
  const { tool, heat, metal, strikes } = step;
  for (const [field, value] of Object.entries({ tool, heat, metal })) {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError(`Missing "${field}" in ${position}.`);
    }
  }
  if (!Number.isInteger(strikes) || strikes < 1) {
    throw new RangeError(`Strike count in ${position} must be a positive integer.`);
  }
  return { tool: tool.trim().toLowerCase(), heat: heat.trim(), metal: metal.trim(), strikes };
}

function instruct(steps) {
  if (!Array.isArray(steps)) {
    throw new TypeError('instruct expects a list of forging actions.');
  }
  const directions = [];
  steps.forEach((raw, index) => {
    const { tool, heat, metal, strikes } = validateStep(raw, index);
    directions.push(`Heat the ${metal} until it is ${heat}.`);
    if (tool === 'anvil') {
      directions.push(`Place the ${heat} ${metal} on the anvil.`);
      directions.push(`Strike it ${strikes} times with a steady hammer.`);
    } else if (tool === 'hardy') {
      directions.push(`Score the ${metal} over the hardy while it stays ${heat}.`);
      directions.push(`Drive the cut home with ${strikes} firm blows.`);
    } else if (tool === 'fuller') {
      directions.push(`Groove the ${metal} along the ${tool}.`);
      directions.push(`Keep an even rhythm while the glow holds at ${heat}.`);
    }
    if (strikes > 20) {
      directions.push(`Rest your arm: ${strikes} blows on the ${tool} will tire it.`);
    }
  });
  return directions;
}

function summarize(steps) {
  const tools = steps.map((step) => step.tool.trim().toLowerCase());
  const unique = [...new Set(tools)];
  const total = steps.reduce((sum, step) => sum + step.strikes, 0);
  return `${unique.length} tools (${unique.join(', ')}) and ${total} blows in all.`;
}

function renderGuide(steps) {
  const lines = instruct(steps).map((line, i) => `${String(i + 1).padStart(2, ' ')}. ${line}`);
  return `${lines.join('\n')}\n\nSummary: ${summarize(steps)}`;
}

function main() {
  const plan = [
    { tool: 'anvil', heat: 'red', metal: 'iron', strikes: 5 },
    { tool: 'hardy', heat: 'orange', metal: 'mild steel', strikes: 24 },
    { tool: 'fuller', heat: 'yellow', metal: 'bronze', strikes: 12 },
    { tool: 'tongs', heat: 'cherry', metal: 'iron', strikes: 3 },
  ];
  console.log(renderGuide(plan));
  try {
    instruct([{ tool: 'anvil', heat: 'red', metal: 'iron', strikes: 0 }]);
  } catch (err) {
    console.error(`Rejected plan: ${err.message}`);
  }
}

main();

module.exports = { instruct, renderGuide, summarize };

