const ALTITUDE_BANDS = ['low', 'moderate', 'high'];
const LARGE_BASKET = 10;

function normalizeAltitude(altitude) {
  const band = String(altitude).trim().toLowerCase();
  if (!ALTITUDE_BANDS.includes(band)) {
    throw new Error(`Unknown target altitude "${altitude}"`);
  }
  return band;
}

function describeBalloon(pattern, capacity) {
  return `Prepare the ${pattern} balloon for ${capacity} passengers.`;
}

function lowAltitudeSteps(pattern, capacity, altitude) {
  const inflation = `Inflate for ${capacity} passengers to reach a ${altitude} altitude.`;
  const tethering = `Keep the ${pattern} balloon tethered until the ground crew signals.`;
  return [inflation, tethering];
}

function moderateAltitudeSteps(pattern, capacity, altitude) {
  const heating = `Heat the envelope for a ${altitude} climb with ${capacity} passengers aboard.`;
  const steadying = `Steady the ${pattern} balloon while the burner builds pressure.`;
  return [heating, steadying];
}

function highAltitudeSteps(capacity, altitude, power) {
  const weather = `Review the weather for a ${altitude} ascent with ${power} burner power.`;
  const checking = `Check the oxygen supply for ${capacity} passengers.`;
  return [weather, checking];
}

function extraWeightStep(pattern, capacity) {
  return `Rebalance the ${pattern} basket, ${capacity} passengers is a heavy load.`;
}

function checklist(balloons) {
  const steps = [];
  for (const balloon of balloons) {
    const { pattern, power, capacity } = balloon;
    const altitude = normalizeAltitude(balloon.altitude);
    steps.push(describeBalloon(pattern, capacity));
    if (altitude === 'low') {
      steps.push(...lowAltitudeSteps(pattern, capacity, altitude));
    } else if (altitude === 'moderate') {
      steps.push(...moderateAltitudeSteps(pattern, capacity, altitude));
    } else {
      steps.push(...highAltitudeSteps(capacity, altitude, power));
    }
    if (capacity > LARGE_BASKET) {
      steps.push(extraWeightStep(pattern, capacity));
    }
  }
  return steps;
}

function main() {
  const flights = [
    { pattern: 'striped', power: 'normal', capacity: 4, altitude: 'low' },
    { pattern: 'checkered', power: 'boosted', capacity: 8, altitude: 'moderate' },
    { pattern: 'golden', power: 'maximum', capacity: 12, altitude: 'High' },
  ];
  const steps = checklist(flights);
  console.log(`Launch procedures for ${flights.length} balloons:`);
  steps.forEach((step, index) => {
    console.log(`${index + 1}. ${step}`);
  });
}

main();

module.exports = { checklist };

