const ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
  'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen',
  'eighteen', 'nineteen'];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
const LUXURY_LIMIT = 10;

function goldInWords(amount) {
  if (!Number.isInteger(amount) || amount < 0) {
    throw new TypeError(`A gold price must be a whole number, got ${amount}`);
  }
  if (amount < ONES.length) {
    return ONES[amount];
  }
  if (amount < 100) {
    const tens = TENS[Math.floor(amount / 10)];
    const rest = amount % 10;
    return rest === 0 ? tens : `${tens}-${ONES[rest]}`;
  }
  throw new RangeError(`No dish in the ledger costs ${amount} gold`);
}

function priceTag(amount) {
  return `${goldInWords(amount)} gold`;
}

function dishLines(dish) {
  const lines = [`${dish.name} for ` + priceTag(dish.price)];
  if (dish.price > LUXURY_LIMIT) {
    lines.push(`Beware, this is a luxury for deep pockets alone`);
  }
  lines.push(`It tastes ${dish.flavor}, just as the cook intends`);
  return lines;
}

function menu(offerings) {
  const { tavernName, hostName, dishes } = offerings;
  if (!tavernName || !hostName) {
    throw new Error('A menu needs both a tavern name and a host name');
  }
  if (!Array.isArray(dishes) || dishes.length === 0) {
    throw new Error(`${tavernName} cannot print a menu without dishes`);
  }
  const welcome = `Welcome to ${tavernName}`;
  const service = `${hostName} at your service`;
  const lines = [[welcome, service].join(', ')];
  lines.push(`Today's special features ${dishes[0].ingredient} fresh from the market`);
  for (const dish of dishes) {
    lines.push(...dishLines(dish));
  }
  lines.push(`Do not forget to tip ${hostName} on your way out`);
  return lines;
}

