    throw new Error(`Room record ${index} is missing a room name`);
  }
  if (!Number.isFinite(room.baseEnergy) || !Number.isFinite(room.peakEnergy)) {
    throw new Error(`Room ${room.name} must have numeric base and peak energy levels`);
  }
  if (typeof room.entitySuspected !== 'string' || room.entitySuspected.trim() === '') {
    throw new Error(`Room ${room.name} is missing the entity suspected`);
  }
}

