    ]
  },
  {
    name: 'Annex',
    year: 1992,
    hazards: [{ type: 'Lead', severity: 'high', area: 'Paint Shop' }]
  }
];

for (const site of sites) {
  console.log(report(site).join('\n'));
  console.log(summarize(site));
}

