function formatSpec(design) {
  const { wingspan, fabric } = design;
  return `Wingspan: ${wingspan} cm, Fabric: ${fabric}`;
}

function formatAction(step) {
  return `${step.action} the ${step.component}`;
}

function formatTension(step) {
  return `Tension level: ${step.tension}`;
}

function isTight(step) {
  return String(step.tension).toLowerCase() === 'tight';
}

function frameCaution(step) {
  return `Caution: a tight ${step.component} can bow or snap the frame`;
}

function validate(design) {
  if (!design || !design.model) {
    throw new Error('A kite design needs a model name');
  }
  if (typeof design.wingspan !== 'number' || design.wingspan <= 0) {
    throw new Error(`Invalid wingspan for the ${design.model}: ${design.wingspan}`);
  }
  if (!design.fabric) {
    throw new Error(`No fabric type given for the ${design.model}`);
  }
  if (!Array.isArray(design.steps) || design.steps.length === 0) {
    throw new Error(`The ${design.model} manual needs at least one assembly step`);
  }
}

function instruct(design) {
  validate(design);
  const lines = [`Manual for the ${design.model}`];
  lines.push(formatSpec(design));

  let count = 0;
  for (const step of design.steps) {
    count += 1;
    lines.push(formatAction(step));
    lines.push(formatTension(step));
    if (isTight(step)) {
      lines.push(frameCaution(step));
    }
  }

  lines.push(`Assembly complete after ${count} steps`);
  lines.push(`Good winds with your ${design.model}!`);
  return lines;
}

const boxKite = {
  model: 'Box Kite',
  wingspan: 90,
  fabric: 'Nylon',
