    { component: 'Spine', action: 'Tie', tension: 'loose' },
    { component: 'Cross Spar', action: 'Slot', tension: 'medium' },
    { component: 'Bridle Line', action: 'Knot', tension: 'tight' }
  ]
};

console.log(instruct(boxKite).join('\n'));

module.exports = { instruct, formatSpec, formatAction, formatTension };

