const WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine'];

function formatTimestamp(seconds) {
  if (!Number.isFinite(seconds)) {
    throw new TypeError(`Timestamp must be a finite number, got ${seconds}`);
  }
  if (seconds < 0) {
    return `T minus ${Math.abs(seconds)} seconds`;
  }
  if (Number.isInteger(seconds) && seconds < WORDS.length) {
    return WORDS[seconds];
  }
  return `${seconds} seconds`;
}

function formatAltitude(altitude) {
  if (altitude === 0) {
    return 'Altitude: ground level';
  }
  return `Altitude: ${altitude.toFixed(1)} m`;
}

function describeConditions(motorClass, windSpeed) {
  return [
    `Motor class ${motorClass} loaded and armed`,
    `Wind speed measured at ${windSpeed} km/h`,
  ];
}

function telemetry(flight) {
  const { vehicle, motorClass, windSpeed, events } = flight;
  if (!vehicle) {
    throw new Error('A vehicle name is required to open a telemetry log');
  }
  if (!Array.isArray(events)) {
    throw new TypeError(`Expected a list of event records for ${vehicle}`);
  }

  const lines = [`${vehicle} is on the pad`];
  lines.push(...describeConditions(motorClass, windSpeed));

  let previousAltitude = null;
  let peak = null;

  for (const { timestamp, type, altitude } of events) {
    lines.push(`At ${formatTimestamp(timestamp)}: ${type}`);
    lines.push(formatAltitude(altitude));
    if (previousAltitude !== null && altitude < previousAltitude) {
      const drop = previousAltitude - altitude;
      lines.push(`Descending: lost ${drop.toFixed(1)} m since last reading`);
    }
    if (peak === null || altitude > peak) {
      peak = altitude;
    }
    previousAltitude = altitude;
  }

  if (peak !== null) {
    lines.push(`Apogee declared at ${peak.toFixed(1)} m`);
  }
  lines.push(`End of mission for ${vehicle}`);
  return lines;
}

