const HOVER_PATTERNS = ['hovering', 'hover', 'stationary', 'motionless', 'suspended'];

function classifiedHeader(location) {
  return `CLASSIFIED REPORT -- Classified header for ${location}`;
}

function witnessPreamble(witness, skyCondition) {
  return `Witness ${witness} reports sky condition: ${skyCondition}.`;
}

function formatOffset(offset) {
  if (typeof offset === 'number') {
    return `T+${offset} minutes`;
  }
  return `${offset}`.trim();
}

function impliesHovering(movement) {
  const normalized = `${movement}`.toLowerCase();
  return HOVER_PATTERNS.some((pattern) => normalized.includes(pattern));
}

function sightingLine(witness, offset, shape) {
  const stamp = formatOffset(offset);
  return `[${stamp}] ${witness} observed a ${shape}`;
}

function movementLine(shape, movement) {
  return `    Movement pattern of the ${shape}: ${movement}.`;
}

function anomalyLine(shape) {
  return `    ANOMALOUS PHYSICS: the ${shape} defied inertia while holding position.`;
}

function durationSummary(count) {
  const noun = count === 1 ? 'observation' : 'observations';
  return `Event duration summary: ${count} ${noun} logged in this file.`;
}

function document(sighting) {
  const { witness, location, skyCondition, observations = [] } = sighting;
  const lines = [classifiedHeader(location), witnessPreamble(witness, skyCondition)];

  observations.forEach((observation) => {
    const { offset, shape, movement } = observation;
    lines.push(sightingLine(witness, offset, shape));
    lines.push(movementLine(shape, movement));
    if (impliesHovering(movement)) {
      lines.push(anomalyLine(shape));
    }
  });

  lines.push(durationSummary(observations.length));
  lines.push(`FILE SEALED under the testimony of ${witness}.`);
  return lines;
}

