const HOURS_LIMIT = 120;

function formatDuration(minutes) {
  if (minutes < 60) {
    return `${minutes} min`;
  }
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const hourPart = `${hours} h`;
  return rest === 0 ? hourPart : `${hourPart} ${rest} min`;
}

function validatePiece(piece) {
  if (!piece || typeof piece !== 'object') {
    throw new TypeError('glaze() expects a piece object');
  }
  const { name, clay, temperature } = piece;
  if (!name || !clay) {
    throw new TypeError(`Incomplete piece: name=${JSON.stringify(name)} clay=${JSON.stringify(clay)}`);
  }
  if (!Number.isFinite(temperature)) {
    throw new TypeError(`Firing temperature must be a number, got ${temperature}`);
  }
  return Array.isArray(piece.coats) ? piece.coats : [];
}

function coatLines(coat, index) {
  const { pigment, technique, drying } = coat;
  if (!pigment || !technique) {
    throw new TypeError(`Coat ${index + 1} is missing a pigment or a technique`);
  }
  const lines = [`Apply ${pigment} pigment`];
  lines.push(`  using the ${technique} technique`);
  lines.push(`  let it dry for ${formatDuration(drying)}`);
  if (drying > HOURS_LIMIT) {
    lines.push(`  that is a long wait - go grab a coffee while the ${pigment} sets`);
  }
  return lines;
}

function glaze(piece) {
  const coats = validatePiece(piece);
