function requireFields(source, fields, label) {
  const missing = fields.filter((field) => source[field] === undefined);
  if (missing.length > 0) {
    throw new Error(`Missing ${label} field(s): ${missing.join(', ')}`);
  }
}

function greeting(promotion, city) {
  return `Welcome to ${promotion} wrestling live from ${city}!`;
}

function ruleExplanation(referee, stipulation) {
  return `Referee ${referee} explains the rules of this ${stipulation} match.`;
}

function actionCall(attacker, defender) {
  return `${attacker} charges straight at ${defender}!`;
}

function maneuverDescription(move, location) {
  return `A picture-perfect ${move} delivered in the ${location}.`;
}

function impactStatement(bodyPart, damage) {
  return `That shot leaves the ${bodyPart} with ${damage} damage.`;
}

function crowdReaction(chant, volume) {
  return `The crowd erupts with "${chant}" at ${volume} volume!`;
}

function eventLines(event, index) {
  requireFields(
    event,
    ['attacker', 'defender', 'move', 'location', 'bodyPart', 'damage', 'chant', 'volume'],
    `event #${index + 1}`
  );
  return [
    actionCall(event.attacker, event.defender),
    maneuverDescription(event.move, event.location),
    impactStatement(event.bodyPart, event.damage),
    crowdReaction(event.chant, event.volume),
  ];
}

function announce(match) {
  requireFields(
    match,
    ['promotion', 'city', 'referee', 'stipulation', 'events', 'winner', 'time', 'nextEvent', 'nextMonth'],
    'match'
  );
  if (!Array.isArray(match.events)) {
    throw new TypeError(`Expected events to be an array, received ${typeof match.events}.`);
  }
  const script = [greeting(match.promotion, match.city), ruleExplanation(match.referee, match.stipulation)];
  match.events.forEach((event, index) => {
    script.push(...eventLines(event, index));
  });
  script.push(`Ring the bell — ${match.winner} takes it at ${match.time}!`);
  script.push(`See you at ${match.nextEvent} this coming ${match.nextMonth}!`);
  return script;
}

