function validateAttraction(attraction) {
  const required = ['theme', 'openingHour', 'supervisor', 'radioChannel', 'rooms',
    'shiftLength', 'breakRoom', 'emergencyCode', 'evacuationExit'];
  const missing = required.filter((key) => attraction[key] === undefined);
  if (missing.length > 0) {
    throw new Error(`Attraction data is missing: ${missing.join(', ')}.`);
  }
  if (!Array.isArray(attraction.rooms)) {
    throw new TypeError(`Expected "rooms" to be an array, received ${typeof attraction.rooms}.`);
  }
  attraction.rooms.forEach((room, index) => {
    if (!room.name) {
      throw new Error(`Room assignment #${index + 1} has no room name.`);
    }
  });
  return attraction;
}

function roomLines(room) {
  const positioning = `Take your place in the ${room.name}`
    + ` and hide ${room.hidingSpot}.`;
  const trigger = `Wait for the ${room.sensorType} to fire`
    + ` when guests reach ${room.victimLocation}.`;
  const action = `Then ${room.movement}`
    + ` while wielding the ${room.prop}.`;
  const vocalization = `Deliver the line "${room.dialogue}"`
    + ` in a ${room.voicePitch} pitch.`;
  return [positioning, trigger, action, vocalization];
}

function scare(attraction) {
  const data = validateAttraction(attraction);
  const welcome = `The ${data.theme} attraction`
    + ` opens at ${data.openingHour} sharp.`;
  const safety = `Safety supervisor ${data.supervisor}`
    + ` monitors radio channel ${data.radioChannel}.`;
  const lines = [welcome, safety];
  for (const room of data.rooms) {
    lines.push(...roomLines(room));
  }
  lines.push(`Your shift runs ${data.shiftLength},`
    + ` with breaks taken in the ${data.breakRoom}.`);
  lines.push(`If you hear code ${data.emergencyCode},`
    + ` lead guests to the ${data.evacuationExit}.`);
  return lines;
}

