  const pressure = `${end.broomPressure} broom pressure`;
  return `Sweepers, ${pressure} and call it loud with "${end.sweeperCall}".`;
}

function backupPlan(end) {
  return `If their guard sits ${end.opponentGuard}, switch to the ${end.takeout} takeout.`;
}

