  return `Step ${movement.stepDirection} into a ${movement.stanceType} stance.`;
}

function defense(movement) {
  return `Execute a ${movement.blockStyle} block at ${movement.targetHeight} height.`;
}

function offense(movement) {
  return `Strike with the ${movement.weaponPart} toward the ${movement.impactPoint}.`;
}

