function temperatureWord(celsius) {
  if (celsius <= 5) return 'bone-shattering';
  if (celsius <= 15) return 'freezing';
  if (celsius <= 22) return 'murky-cool';
  return 'suspiciously warm';
}

function conditionLine(trench, temperature) {
  const descriptor = temperatureWord(temperature);
  return `The ${trench} is a ${descriptor} ${temperature} degrees today.`;
}

function safetyLine(diver, tube) {
  return `Safety protocol: ${diver} is on standby with a ${tube}.`;
}

function introLine(lap) {
  return `Up next, ${lap.swimmer}, wearing a ${lap.costume}.`;
}

function techniqueLine(lap) {
  const style = `${lap.snorkelStyle} snorkel work`;
  return `Technique: ${style} paired with a ${lap.flipperKick} flipper kick.`;
}

function obstacleLine(lap) {
  const mud = `${lap.mudDepth} of mud`;
  return `Obstacles: ${mud} plus a nasty ${lap.weedTangle} weed tangle.`;
}

function timingLine(lap) {
  return `Result: ${lap.lapTime} on the clock, finished with a ${lap.gasp}.`;
}

function lapLines(lap) {
  return [introLine(lap), techniqueLine(lap), obstacleLine(lap), timingLine(lap)];
}

function cleaningLine(sponsor, shower) {
  return `Towels by ${sponsor}; hose yourself down at the ${shower}.`;
}

function closingLine(stench, cheer) {
  const stenchNote = `an overall stench of ${stench}`;
  return `We end with ${stenchNote} and cheering at ${cheer}.`;
