function cue(spectacle) {
  const script = [];
  const { planetarium, domeDiameter, software, technician, effects } = spectacle;

  script.push(`Venue ${planetarium} prepared with a ${domeDiameter} dome.`);
  script.push(`System running ${software} under technician ${technician}.`);

  effects.forEach((effect) => {
    script.push(`Beams generated in ${effect.colorPalette} tracing ${effect.geometryPattern}.`);
    script.push(`Mapped onto ${effect.projectionSurface} with transitions at ${effect.transitionSpeed}.`);
    script.push(`Audio sync locked to ${effect.audioSyncPoint}, bass drop at ${effect.bassDropTiming}.`);
    script.push(`Laser intensity held at ${effect.laserIntensity} above eye level ${effect.audienceEyeLevel}.`);
  });

  script.push(`Shutdown begins with fans at ${spectacle.coolingFanSpeed}, power down ${spectacle.powerDownTime}.`);
  script.push(`Exit music ${spectacle.exitMusicTrack} plays as house lights fade ${spectacle.houseLightsFadeSpeed}.`);

  return script;
}

function validate(spectacle) {
  const missing = ['planetarium', 'domeDiameter', 'software', 'technician']
    .filter((key) => !spectacle[key]);
  if (missing.length) {
    throw new Error(`Spectacle is missing: ${missing.join(', ')}.`);
  }
  if (!Array.isArray(spectacle.effects) || spectacle.effects.length === 0) {
    throw new Error(`Spectacle for ${spectacle.planetarium} declares no effects.`);
  }
  return spectacle;
}

function render(spectacle) {
  const lines = cue(validate(spectacle));
  return lines
    .map((line, index) => `${String(index + 1).padStart(3, ' ')}. ${line}`)
    .join('\n');
}

