  return greeting + venue;
}

function hardwareLine(equipmentBrand, chalkDust) {
  const bars = `The bars are ${equipmentBrand}`;
  const chalk = ` and there is ${chalkDust} of chalk dust in the air.`;
  return bars + chalk;
}

function featLines(feat) {
  const approach = `${feat.athlete} steps up to the platform`;
  const gaze = ` with ${feat.eyeIntensity} in his eyes.`;
  const grip = `He grips the ${feat.implement}`;
  const drive = ` and drives ${feat.weight} off the ground.`;
  const haul = `He hauls it ${feat.distance}`;
  const strain = ` with ${feat.muscleStrain} showing on every step.`;
  const release = `He drops the load to ${feat.audienceReaction}`;
  const whistle = ` as the referee's whistle ${feat.whistle}.`;
  return [approach + gaze, grip + drive, haul + strain, release + whistle];
}

function podiumLine(trophySize, confettiColor) {
  const trophy = `On the podium a ${trophySize} trophy is raised`;
  const confetti = ` under ${confettiColor} confetti.`;
  return trophy + confetti;
}

function charityLine(donation, beneficiary) {
  const pledge = `The organizers pledge ${donation}`;
  const recipient = ` to ${beneficiary} before the lights go down.`;
  return pledge + recipient;
}

function summarize(competition) {
  const { eventName, hostCity, equipmentBrand, chalkDust, feats,
    trophySize, confettiColor, charityDonation, localBeneficiary } = competition;

  if (!Array.isArray(feats)) {
    throw new TypeError(`Expected feats to be an array, received ${typeof feats}.`);
