  const lines = [
    welcomeLine(eventName, hostCity),
    hardwareLine(equipmentBrand, chalkDust),
  ];
  feats.forEach((feat) => lines.push(...featLines(feat)));
  lines.push(podiumLine(trophySize, confettiColor));
  lines.push(charityLine(charityDonation, localBeneficiary));
  return lines;
}

