const REQUIRED_FIELDS = [
  'patternName',
  'weaverName',
  'warpFiber',
  'warpEnds',
  'settDensity',
  'weftFiber',
  'weftColor',
  'treadleSequence',
  'finishMethod',
];

function validatePattern(pattern) {
  if (pattern === null || typeof pattern !== 'object') {
    throw new TypeError(`Expected a pattern object, received ${typeof pattern}.`);
  }
  const missing = REQUIRED_FIELDS.filter((field) => {
    const value = pattern[field];
    return value === undefined || value === null || String(value).trim() === '';
  });
  if (missing.length > 0) {
    throw new Error(`Incomplete draft: missing ${missing.join(', ')}.`);
  }
}

function draft(pattern) {
  validatePattern(pattern);
  const {
    patternName,
    weaverName,
    warpFiber,
    warpEnds,
    settDensity,
    weftFiber,
    weftColor,
    treadleSequence,
    finishMethod,
  } = pattern;

  return [
    `Weaving draft for ${patternName} by ${weaverName}.`,
    `Wind the warp using ${warpFiber}.`,
    `Total warp ends required: ${warpEnds}.`,
    `Thread the reed at a sett of ${settDensity} ends per inch.`,
    `Prepare the shuttle with ${weftFiber} weft.`,
    `Weft color sequence involves ${weftColor}.`,
    `Depress treadles in a ${treadleSequence} pattern.`,
    'Beat the fell line firmly.',
    `Advance the warp to continue and finish with ${finishMethod}.`,
  ];
}

function numberInstructions(instructions) {
  const width = String(instructions.length).length;
  return instructions.map((text, index) => {
    const label = String(index + 1).padStart(width, ' ');
    return `${label}. ${text}`;
  });
}

function renderDraft(pattern) {
  const heading = `=== ${pattern.patternName.toUpperCase()} ===`;
  const body = numberInstructions(draft(pattern)).join('\n');
  return `${heading}\n${body}`;
}

function main() {
  const herringbone = {
    patternName: 'herringbone',
    weaverName: 'Sarah',
    warpFiber: 'cotton',
    warpEnds: 'four hundred',
    settDensity: 'twenty',
    weftFiber: 'wool',
    weftColor: 'blue',
    treadleSequence: 'twill',
    finishMethod: 'hemstitch',
  };
  console.log(renderDraft(herringbone));
  try {
    draft({ ...herringbone, weftColor: '' });
  } catch (error) {
    console.error(`Draft rejected: ${error.message}`);
  }
}

main();

module.exports = { draft, renderDraft, numberInstructions };

