function celsiusToFahrenheit(celsius) {
  if (typeof celsius !== 'number' || Number.isNaN(celsius)) {
    throw new TypeError(`celsiusToFahrenheit expects a number, got ${JSON.stringify(celsius)}`);
  }
  return celsius * 9 / 5 + 32;
}

function parseCelsius(text) {
  const trimmed = String(text).trim().replace(/\s*°?\s*C$/i, '');
  const value = Number(trimmed);
  if (trimmed === '' || Number.isNaN(value)) {
    throw new Error(`Cannot read a Celsius value from "${text}"`);
  }
  return value;
}

function formatTemperature(value, unit) {
  const rounded = Math.round(value * 100) / 100;
  return `${rounded}°${unit}`;
}

function describe(celsius) {
  const fahrenheit = celsiusToFahrenheit(celsius);
  return `${formatTemperature(celsius, 'C')} = ${formatTemperature(fahrenheit, 'F')}`;
}

function classify(celsius) {
  if (celsius <= 0) return 'freezing';
  if (celsius >= 100) return 'boiling';
  if (celsius >= 30) return 'hot';
  return 'moderate';
}

function buildTable(celsiusValues) {
  return celsiusValues.map((celsius) => {
    const label = classify(celsius);
    return `${describe(celsius).padEnd(22)} (${label})`;
  });
}

function convertReadings(readings) {
  const results = [];
  const errors = [];
  readings.forEach((reading, index) => {
    try {
      const celsius = parseCelsius(reading);
      results.push({ celsius, fahrenheit: celsiusToFahrenheit(celsius) });
    } catch (err) {
      errors.push(`reading #${index + 1}: ${err.message}`);
    }
  });
  return { results, errors };
}

function main() {
  const table = buildTable([-40, 0, 25, 37, 100]);
  console.log('Conversion table:');
  table.forEach((row) => console.log(`  ${row}`));

  const { results, errors } = convertReadings(['18.5 C', '  -3°C', 'warm', '42']);
  const summary = results.map((r) => formatTemperature(r.fahrenheit, 'F')).join(', ');
  console.log(`Parsed ${results.length} of 4 readings: ${summary}`);

  const average = results.reduce((sum, r) => sum + r.fahrenheit, 0) / results.length;
  console.log(`Average parsed temperature: ${formatTemperature(average, 'F')}`);

  for (const problem of errors) {
    console.warn(`Skipped ${problem}`);
  }
}

main();

module.exports = { celsiusToFahrenheit, parseCelsius, formatTemperature, describe, buildTable, convertReadings };

