function fizzBuzz(n) {
  if (!Number.isInteger(n)) {
    throw new TypeError(`fizzBuzz expects an integer, received ${typeof n}: ${String(n)}`);
  }
  if (n < 0) {
    throw new RangeError(`fizzBuzz expects a non-negative bound, received ${n}`);
  }
  const result = [];
  for (let i = 1; i <= n; i += 1) {
    const byThree = i % 3 === 0;
    const byFive = i % 5 === 0;
    if (byThree && byFive) {
      result.push('FizzBuzz');
    } else if (byThree) {
      result.push('Fizz');
    } else if (byFive) {
      result.push('Buzz');
    } else {
      result.push(i);
    }
  }
  return result;
}

function formatSequence(values, separator = ', ') {
  return values.map((value) => `${value}`).join(separator);
}

function summarize(values) {
  const counts = { Fizz: 0, Buzz: 0, FizzBuzz: 0, numbers: 0 };
  for (const value of values) {
    if (typeof value === 'number') {
      counts.numbers += 1;
    } else {
      counts[value] += 1;
    }
  }
  return counts;
}

function report(n) {
  const values = fizzBuzz(n);
  const counts = summarize(values);
  const lines = [`fizzBuzz(${n}) -> [${formatSequence(values)}]`];
  lines.push(`  plain numbers kept: ${counts.numbers}`);
  lines.push(`  Fizz: ${counts.Fizz}, Buzz: ${counts.Buzz}, FizzBuzz: ${counts.FizzBuzz}`);
  const ratio = n === 0 ? 0 : ((n - counts.numbers) / n) * 100;
  lines.push(`  replaced: ${ratio.toFixed(1)}% of the range`);
  return lines.join('\n');
}

function main(argv) {
  const bounds = argv.length > 0 ? argv.map(Number) : [5, 3, 15];
  for (const bound of bounds) {
    try {
      console.log(report(bound));
    } catch (error) {
      console.error(`skipping input: ${error.message}`);
    }
  }
}

main(process.argv.slice(2));

module.exports = { fizzBuzz, formatSequence, summarize, report };

