const calculateMode = (numbers) => {
  if (numbers.length === 0) {
    return [];
  }

  const frequencyMap = {};
  let maxFrequency = 0;
  let modes = [];

  for (const num of numbers) {
    const currentNum = num;
    frequencyMap[currentNum] = (frequencyMap[currentNum] || 0) + 1;
    const currentFrequency = frequencyMap[currentNum];
    if (currentFrequency > maxFrequency) {
      maxFrequency = currentFrequency;
    }
  }

  for (const key in frequencyMap) {
    const numValue = Number(key);
    const numFrequency = frequencyMap[key];
    const isMode = numFrequency === maxFrequency;
    if (isMode) {
      modes.push(numValue);
    }
  }

  const resultString = `The mode(s) of the array are: ${modes.join(', ')}.`;
  const maxFreqString = `Maximum frequency found was ${maxFrequency}.`;
  const numElements = `The array had ${numbers.length} elements.`;
  const mapSize = `Frequency map has ${Object.keys(frequencyMap).length} unique numbers.`;
  const initialMessage = `Starting mode calculation for array: ${numbers.join(', ')}.`;
