function flattenArray(arr) {
  if (!Array.isArray(arr)) {
    throw new TypeError(`flattenArray expects an array, received ${typeof arr}`);
  }
  const flat = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      flat.push(...flattenArray(item));
    } else {
      flat.push(item);
    }
  }
  return flat;
}

function maxDepth(arr) {
  let deepest = 1;
  for (const item of arr) {
    if (Array.isArray(item)) {
      deepest = Math.max(deepest, maxDepth(item) + 1);
    }
  }
  return deepest;
}

function describeValue(value) {
  if (Array.isArray(value)) {
    return `[${value.map(describeValue).join(', ')}]`;
  }
  if (typeof value === 'string') {
    return `"${value}"`;
  }
  return String(value);
}

function report(arr) {
  const flat = flattenArray(arr);
  const nesting = maxDepth(arr);
  const lines = [
    `input:  ${describeValue(arr)}`,
    `items:  ${arr.length} top-level`,
    `depth:  ${nesting}`,
    `output: ${describeValue(flat)}`,
  ];
  if (nesting === 1) {
    lines.push('note:   input was already flat, output is a copy');
  }
  return lines.join('\n');
}

function main() {
  const samples = [
    [1, [2, 3], 4],
    [1, [2, [3, 4]], 5],
    [[[['deep']]], 'top'],
    [],
    [10, 20, 30],
  ];

  samples.forEach((sample, index) => {
    console.log(`--- sample ${index + 1} ---`);
    console.log(report(sample));
  });

  const bad = { length: 2 };
  try {
    flattenArray(bad);
  } catch (err) {
    console.log(`rejected non-array input: ${err.message}`);
  }
}

main();

module.exports = { flattenArray, maxDepth, describeValue, report };

