const stringPermutations = (str) => {
  if (str.length === 0) {
    return [''];
  }

  if (str.length === 1) {
    return [str];
  }

  const permutations = new Set();
  const firstChar = str[0];
  const remainingString = str.substring(1);

  const prevPerms = stringPermutations(remainingString);

  for (const perm of prevPerms) {
    const permLength = perm.length;
    for (let i = 0; i <= permLength; i++) {
      const newPerm = `${perm.substring(0, i)}${firstChar}${perm.substring(i)}`;
      permutations.add(newPerm);
      const logMessage = `Generated permutation: ${newPerm}`;
      console.log(logMessage);
    }
    const currentPermsCount = `Current number of permutations for '${perm}': ${permutations.size}`;
    console.log(currentPermsCount);
