const rotateArray = (nums, k) => {
  const n = nums.length;
  const effectiveK = k % n;

  if (effectiveK === 0) {
    return nums;
  }

  const rotatedPart = nums.slice(n - effectiveK);
  const remainingPart = nums.slice(0, n - effectiveK);

  const result = rotatedPart.concat(remainingPart);

  console.log(`Original array: ${nums}`);
  console.log(`Rotation steps: ${k}`);
  console.log(`Effective steps: ${effectiveK}`);
  console.log(`The rotated part is: ${rotatedPart}`);
  console.log(`The remaining part is: ${remainingPart}`);
  console.log(`Final array after rotation: ${result}`);

  return result;
};

// Example usage:
// rotateArray([1, 2, 3, 4, 5, 6, 7], 3);
// rotateArray([-1, -100, 3, 99], 2);

