const MONTH_NAMES = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function getDaysInMonth(year, month) {
  if (!Number.isInteger(year)) {
    throw new TypeError(`year must be an integer, received ${year}`);
  }
  if (!Number.isInteger(month)) {
    throw new TypeError(`month must be an integer, received ${month}`);
  }
  if (month < 1 || month > 12) {
    throw new RangeError(`month must be between 1 and 12, received ${month}`);
  }
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) {
    return 29;
  }
  return lengths[month - 1];
}

function describeMonth(year, month) {
  const days = getDaysInMonth(year, month);
  return `${MONTH_NAMES[month - 1]} ${year} has ${days} days`;
}

function getDaysInYear(year) {
  let total = 0;
  for (let month = 1; month <= 12; month += 1) {
    total += getDaysInMonth(year, month);
  }
  return total;
}

function buildYearReport(year) {
  const kind = isLeapYear(year) ? 'leap year' : 'common year';
  const lines = [`${year} is a ${kind} with ${getDaysInYear(year)} days`];
  for (let month = 1; month <= 12; month += 1) {
    const label = MONTH_NAMES[month - 1].padEnd(9, ' ');
    lines.push(`  ${label} ${String(getDaysInMonth(year, month)).padStart(2, ' ')}`);
  }
  return lines.join('\n');
}

function main() {
  console.log(describeMonth(2023, 2));
  console.log(describeMonth(2024, 2));
  console.log(buildYearReport(2024));

  const centuries = [1900, 2000, 2100];
  for (const year of centuries) {
    const februaryDays = getDaysInMonth(year, 2);
    console.log(`February ${year}: ${februaryDays} days`);
  }

  try {
    getDaysInMonth(2024, 13);
  } catch (error) {
    console.log(`Rejected invalid input: ${error.message}`);
  }
}

main();

module.exports = { getDaysInMonth, isLeapYear, getDaysInYear, describeMonth, buildYearReport };

