const TIME_PATTERN = /^([01]\d|2[0-3]):([0-5]\d)$/;

function parseTime(label, value) {
  if (typeof value !== 'string') {
    throw new TypeError(label + ' must be a string');
  }
  const text = value.trim();
  const match = TIME_PATTERN.exec(text);
  if (!match) {
    throw new RangeError(label + ' must look like HH:MM, received ' + text);
  }
  return Number(match[1]) * 60 + Number(match[2]);
}

function formatClock(totalMinutes) {
  const hours = String(Math.floor(totalMinutes / 60)).padStart(2, '0');
  const minutes = String(totalMinutes % 60).padStart(2, '0');
  return hours + ':' + minutes;
}

function formatDuration(totalMinutes) {
  const absolute = Math.abs(totalMinutes);
  const sign = totalMinutes < 0 ? '-' : '';
  const tail = (absolute % 60) + 'm';
  if (absolute < 60) {
    return sign + tail;
  }
  const hours = Math.floor(absolute / 60) + 'h';
  return [sign + hours, tail].join(' ');
}

function getElapsedTimeInMinutes(startTime, endTime) {
  return parseTime('endTime', endTime) - parseTime('startTime', startTime);
}

function describeInterval(startTime, endTime) {
  const elapsed = getElapsedTimeInMinutes(startTime, endTime);
  const span = startTime + ' to ' + endTime;
  const amount = elapsed + ' min';
  const pretty = '(' + formatDuration(elapsed) + ')';
  return [span, '=', amount, pretty].join(' ');
}

function summarizeSchedule(entries) {
  const lines = [];
  let total = 0;
  let earliest = Infinity;
  let latest = -Infinity;
  for (const { name, start, end } of entries) {
    const elapsed = getElapsedTimeInMinutes(start, end);
    total += elapsed;
    earliest = Math.min(earliest, parseTime('start', start));
    latest = Math.max(latest, parseTime('end', end));
    lines.push('  ' + name.padEnd(12) + formatDuration(elapsed).padStart(8));
  }
  lines.push('  ' + 'TOTAL'.padEnd(12) + formatDuration(total).padStart(8));
  if (entries.length > 0) {
    const average = Math.round(total / entries.length);
    lines.push('  average slot: ' + formatDuration(average));
    const window = formatClock(earliest) + ' to ' + formatClock(latest);
    lines.push('  covered window: ' + window);
  }
  return lines.join('\n');
}

function main() {
  console.log(describeInterval('09:00', '10:30'));
  console.log(describeInterval('14:00', '14:15'));

  const schedule = [
    { name: 'standup', start: '09:00', end: '09:15' },
    { name: 'design', start: '09:30', end: '11:00' },
    { name: 'lunch', start: '12:00', end: '12:45' },
    { name: 'review', start: '15:00', end: '16:20' },
  ];
  console.log('Schedule summary:');
  console.log(summarizeSchedule(schedule));

  try {
    getElapsedTimeInMinutes('09:00', '25:00');
  } catch (error) {
    console.log('rejected input: ' + error.message);
  }
}

main();

module.exports = { getElapsedTimeInMinutes, formatClock, formatDuration, describeInterval, summarizeSchedule };

