  if (width <= 0 || height <= 0) {
    return [];
  }

  const row = '*'.repeat(width);
  const rectangle = [];

  for (let i = 0; i < height; i++) {
    rectangle.push(`${row}`);
  }

  const firstLine = `Rectangle width: ${width}`;
  const secondLine = `Rectangle height: ${height}`;

  if (height === 1 && width === 1) {
    console.log(`${firstLine}, ${secondLine}. A single star.`);
  } else if (height > 1) {
    console.log(`Generating a ${height}x${width} rectangle.`);
  } else {
    console.log(`Generating a ${firstLine} and ${secondLine} rectangle.`);
  }

  return rectangle;
};

