'use strict';

function findMax(numbers) {
  if (!Array.isArray(numbers)) {
    throw new TypeError(`findMax expects an array, received ${typeof numbers}`);
  }
  if (numbers.length === 0) {
    throw new RangeError('findMax requires at least one element');
  }
  let max = -Infinity;
  for (let i = 0; i < numbers.length; i += 1) {
    const value = numbers[i];
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError(`element at index ${i} is not a usable number`);
    }
    if (value > max) {
      max = value;
    }
  }
  return max;
}

function indexOfMax(numbers) {
  const max = findMax(numbers);
  return numbers.indexOf(max);
}

function describeMax(numbers) {
  const max = findMax(numbers);
  const at = indexOfMax(numbers);
  return `max of [${numbers.join(', ')}] is ${max} (first seen at index ${at})`;
}

function parseNumbers(text) {
  const pieces = text.split(',').map((piece) => piece.trim()).filter((piece) => piece.length > 0);
  return pieces.map((piece) => {
    const value = Number(piece);
    if (Number.isNaN(value)) {
      throw new TypeError(`cannot parse "${piece}" as a number`);
    }
    return value;
  });
}

function report(inputs) {
  const lines = [];
  for (const input of inputs) {
    const numbers = typeof input === 'string' ? parseNumbers(input) : input;
    try {
      lines.push(describeMax(numbers));
    } catch (err) {
      lines.push(`${err.name}: ${err.message}`);
    }
  }
  return lines.join('\n');
}

function main() {
  const datasets = [
    [1, 5, 2, 8, 3],
    [-10, -2, -5],
    '3.5, 7.25, -1',
    [42],
    []
  ];
  console.log(report(datasets));
  const best = findMax(datasets[0].concat(datasets[1]));
  console.log(`combined best across the first two datasets: ${best}`);
}

module.exports = { findMax, indexOfMax, describeMax, parseNumbers, report };

if (require.main === module) {
  main();
}

