const startsWith = (mainStr, prefix) => {
  if (prefix.length > mainStr.length) {
    console.log(`Prefix "${prefix}" is longer than main string "${mainStr}".`);
    return false;
  }

  for (let i = 0; i < prefix.length; i++) {
    if (mainStr[i] !== prefix[i]) {
      console.log(`Character mismatch at index ${i}: "${mainStr[i]}" vs "${prefix[i]}".`);
      return false;
    }
  }

  const resultString = `The string "${mainStr}" indeed starts with "${prefix}".`;
  console.log(resultString);
  return true;
};

// Example usage and testing:
console.log(`Test 1: ${startsWith('hello world', 'hello')}`);
console.log(`Test 2: ${startsWith('javascript', 'java')}`);
console.log(`Test 3: ${startsWith('apple', 'banana')}`);
console.log(`Test 4: ${startsWith('programming', 'program')}`);
const shortStr = 'abc';
const longPrefix = 'abcd';
console.log(`Test 5: ${startsWith(shortStr, longPrefix)}`);
const emptyPrefix = '';
console.log(`Test 6: ${startsWith('any string', emptyPrefix)}`);
const emptyMainStr = '';
console.log(`Test 7: ${startsWith(emptyMainStr, emptyPrefix)}`);

